(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-mixtral-of-experts-2024"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-1\">一 · 一个真实在线服务的现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-2\">二 · 稠密扩张的三重代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-3\">三 · 旧方案在 MoE 面前的失效点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-4\">四 · 为什么非改不可：尾延迟而非均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-5\">五 · 论文给出的机制，以及它没有给出的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-6\">六 · 落在具体机制上的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-7\">七 · 路由偏斜下的容量截断：旧方案在在线服务里的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-8\">八 · 从请求形态到每层 token 计数：可核查的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-9\">九 · 并发、批大小与容量因子的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-10\">十 · 尾延迟的三个来源与各自的测量方法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-11\">十一 · 负载如何反向塑造方案：入口整形与运行时旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-12\">十二 · 显存预算里的三方争夺与可核查的容量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-13\">十三 · 失败模式的可观测信号与判断准则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-14\">十四 · 负载形态如何反过来锁死容量因子与并行拓扑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-15\">十五 · 路由张量与分组 GEMM 的 kernel 形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-16\">十六 · 数据类型：FP16/BF16 到 FP8 再到 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-17\">十七 · 累加精度与误差传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-18\">十八 · Blackwell 特性如何落到这条链上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-19\">十九 · 融合边界与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-20\">二十 · 分组 GEMM 的形状抖动与低精度累加的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-21\">二十一 · 显存账本的三条主线：专家权重、KV cache、路由中间张量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-22\">二十二 · 带宽瓶颈的位置：权重流、KV 流与 All-to-All 流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-23\">二十三 · 可复算的显存预算：从符号到具体档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-24\">二十四 · 分页、压缩与复用的组合策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-25\">二十五 · 容量因子与显存账本的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-26\">二十六 · 连续批处理与分组 GEMM 的形状抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-27\">二十七 · chunked prefill 与预填/解码混批的相互干扰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-28\">二十八 · 优先级、抢占与容量因子的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-29\">二十九 · 分离式预填/解码对 All-to-All 的重构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-30\">三十 · 尾延迟的分解与可观测项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-31\">三十一 · 容量因子之外的调度边界：路由偏斜如何吃掉连续批处理的红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-32\">三十二 · 切分维度：TP 切的是矩阵，EP 切的是 token</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-33\">三十三 · Blackwell 上的物理链路：NVLink 5 与 NVSwitch 决定 All-to-All 的下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-34\">三十四 · NIXL 与传输层：把“搬 token”从集合通信里解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-35\">三十五 · All-Reduce 与 All-to-All 的瓶颈判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-36\">三十六 · 通信何时成为瓶颈：三个可操作的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-37\">三十七 · 专家并行的通信边界：All-to-All 何时压过分组 GEMM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-38\">三十八 · 精度塌陷：从门控权重到分组 GEMM 的数值链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-39\">三十九 · OOM：专家权重、KV cache 与路由中间张量的三方挤占</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-40\">四十 · 批抖动与尾延迟：分组 GEMM 形状与 All-to-All 排队的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-41\">四十一 · 静默降级：容量丢弃与路由塌缩的无告警失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-42\">四十二 · 监控、定位与回滚：把旋钮做成可回退的状态机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-43\">四十三 · 路由偏斜下的五类失效与可观测闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-44\">四十四 · 口径先于数字：可比的三个锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-45\">四十五 · 硬件档位与并行拓扑：材料未给出的部分怎么处理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-46\">四十六 · batch 与并发：容量因子把两者绑在一起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-47\">四十七 · 指标口径：TTFT、TPOT、吞吐、显存、功耗各自的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-48\">四十八 · 哪些提升不可比：四类典型误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-49\">四十九 · 消融维度的口径：没有数字时怎么读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-50\">五十 · 基准口径的失效边界：从「平均吞吐」到「尾延迟账本」</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-51\">五十一 · 迁移到不同专家数与并行拓扑时的重排代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-52\">五十二 · 容量因子在变长负载与长上下文下的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-53\">五十三 · 低精度迁移：路由打分与门控权重的数值边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-54\">五十四 · 从语言模型迁到其他领域：路由语义的前提是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-55\">五十五 · 规模上限：什么条件下这套方案不再划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-56\">五十六 · 迁移检查清单：把判断落成可执行项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixtral-of-experts-2024-sec-57\">五十七 · 迁移到新模型时的三个硬约束</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:543px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 543.2 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入调度器后被切分为 token 批次，按序列长度与并发度组成推理…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每层先由路由器对每个 token 计算 N 维专家打分，取 top-k…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按容量因子计算每专家可接收的 token 上限，超出容量的 token…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">token 按专家编号重排为分组批次，在专家并行拓扑下经 All-to…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">各设备对本地专家执行分组 GEMM，完成后经反向 All-to-All…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">门控权重与专家输出加权求和写回残差流，进入下一层；KV cache 按…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-1\">一 · 一个真实在线服务的现场</h3>\n<p>设想一个部署在 GB200 NVL72 机架上的对话服务：入口网关把请求切成 token 批次，调度器按并发度拼成推理批，逐层推进。某一层的前馈子层原本是一次规整的稠密 GEMM——批内 B 个 token 全部乘同一组权重，M 维等于 B，形状在批形成的那一刻就确定，kernel 的 tile 划分、流水线深度、SM 占用率都可以在编译期算死。这是稠密推理栈最舒服的地方：形状可预测，吞吐可预测，SLO 可预测。问题在于，当模型参数从百亿级抬到更大的量级，这条路径立刻撞墙——每 token 计算量随参数量线性上涨，单卡显存装不下权重，多卡切分又要把激活反复搬运，吞吐与显存容量同时被掐住。工程上于是出现两条分岔：一条是继续堆稠密 GEMM、靠更激进的量化与并行硬扛；另一条是把前馈层拆成多个专家、每 token 只走其中少数几个。Mixtral of Experts 走的是后一条，而它一旦落地，上面那个“形状可预测”的前提就被彻底拆掉了。</p>\n<p>这篇论文之前的推理栈主流做法，本质上是“稠密假设”下的一整套优化：算子融合、连续批处理、张量并行切分、KV cache 分页管理，全部建立在“每 token 计算路径相同”之上。连续批处理之所以能稳定提升吞吐，是因为新请求插入批内不会改变任何一层的计算图形状，只是把 M 维从 B 变成 B+ΔB。张量并行之所以能线性扩展，是因为每张卡切的是同一块权重的一个切片，通信是规整的 All-Reduce。这套栈的每一个旋钮——批大小、并行度、量化位宽——都对应一个单调的代价曲线。MoE 把这条曲线打断了。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-2\">二 · 稠密扩张的三重代价</h3>\n<p>稠密模型扩大参数，代价是三条同时收紧的绳子。第一条是计算：每 token 的 FLOPs 与前馈层参数量成正比，参数量翻倍，单 token 计算量翻倍，在固定 SLO 下吞吐直接腰斩。第二条是显存：权重必须全部驻留，B200 单卡容量再大也装不下任意大的模型，于是必须切分，切分就带来激活与梯度的跨卡搬运。第三条是带宽：解码阶段每生成一个 token 都要把全部权重从 HBM 读一遍，这是典型的 memory-bound 区间，算力空转、带宽吃满。三条绳子互相牵制——想用更大批提升吞吐，KV cache 与激活显存就顶上来；想用更低精度省带宽，数值稳定性又要重新验证。</p>\n<p>用公式表述这条约束链：设前馈层参数量为 P_ffn、批内 token 数为 B、单卡 HBM 带宽为 W，则解码一步该层权重读取时间近似为</p>\n<div class=\"formula\">$$T_{\\mathrm{step}}\\approx\\frac{P_{\\mathrm{ffn}}\\cdot b_{\\mathrm{w}}}{W},\\qquad \\mathrm{Throughput}\\approx\\frac{B}{T_{\\mathrm{step}}}$$</div>\n<p>其中 b_w 是每权重字节数。这个式子说明：稠密路径下吞吐的上界由“权重字节数 ÷ 带宽”锁死，与批大小无关——加批只是把固定开销摊薄，摊不掉的权重读取是硬成本。这就是为什么工程上非改不可：不是优化不够努力，而是稠密结构本身把每 token 计算量与总参数量绑死，任何调度技巧都只是在常数项上做文章。</p>\n<p>一个具体例子：某层前馈若为单个稠密 FFN，批内 512 个 token 全部参与同一组 GEMM，M=512 的 tile 划分饱满、SM 利用率高，但权重读取量是固定的全部 FFN 参数。换成 8 个专家、top-2 路由后，每 token 只读 2 个专家的权重，权重读取量降到原来的四分之一量级，代价是 GEMM 的 M 维从 512 变成“每个专家实际收到的 token 数”，八个专家的 M 维之和仍约等于 1024（因为每 token 走两个专家），但每个专家的 M 维可能从 30 到 200 不等——形状从“一个饱满的大 GEMM”碎成“八个胖瘦不一的 GEMM”。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-3\">三 · 旧方案在 MoE 面前的失效点</h3>\n<p>失效点一：连续批处理的形状假设。连续批处理的前提是“插入新请求不改变计算图形状”。MoE 下每层路由是逐 token、逐层独立决策的，批内 token 的专家归属在每一层都重新洗牌，分组 GEMM 的 M 维随路由分布动态变化。调度器即便把批大小控得再稳，也控不住某一层某个专家突然被 60% 的 token 选中——那台设备的 GEMM 排队，其余设备空转。批调度层面的平滑，掩盖不了算子层面的抖动。</p>\n<p>失效点二：容量因子把负载不均转成丢弃。系统按容量因子 C 计算每专家上限，超出上限的 token 被掩码丢弃、该层输出为零、只保留残差。丢弃率随路由偏斜上升，而偏斜是流量本身的属性，不是调度能消除的。容量因子设小，丢弃多、生成质量掉；设大，显存与计算预留浪费、吞吐掉。这个旋钮没有“正确值”，只有在 SLO 与质量之间的折中点。旧栈里没有任何一个参数对应这种“按专家截断”的语义，调度器只能被动接受。</p>\n<p>失效点三：专家并行引入 All-to-All。稠密张量并行的通信是规整的 All-Reduce，通信量正比于激活大小、与数据内容无关。MoE 的专家并行要求 token 按专家编号重排后发往持有对应专家的设备，再反向送回，通信量与路由分布相关——偏斜流量下最忙设备的入队 token 最多，All-to-All 的尾延迟被单点放大。旧栈的通信规划假设“每卡收发量对称”，在 MoE 下这个假设不成立。</p>\n<p>失效点四：显存规划的双重账本。稠密模型的显存账本是“权重 + KV cache + 激活”，权重是常数。MoE 下权重仍是全部专家驻留（总参数量远大于激活参数量），但激活侧多出路由张量、专家分组索引、容量掩码这些中间结构，它们的尺寸随批大小与专家数增长。容量规划必须同时计入专家权重、KV cache 与路由中间张量，三者对批大小的敏感度不同，旧栈的单一口径算不准。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-4\">四 · 为什么非改不可：尾延迟而非均值</h3>\n<p>在线服务的 SLO 以首 token 延迟与每 token 间隔衡量，违约由尾延迟触发，不由均值触发。稠密栈优化的是均值吞吐，MoE 把方差推到了前台：分组 GEMM 形状抖动、All-to-All 偏斜排队、容量丢弃的随机性，三者叠加让 P99 与 P50 的差距拉大。只报告平均吞吐会系统性低估违约风险——这正是旧方案失效的工程本质：它的指标体系与 MoE 的代价结构不匹配。</p>\n<p>伪代码层面，一个解码步的链路可以写成：</p>\n<div class=\"formula\">$$\\begin{aligned}\n&amp;g = W_r x \\quad\\text{(B×N 打分)}\\\\\n&amp;S = \\mathrm{TopK}(g, k),\\quad w = \\mathrm{softmax}(g)_S\\\\\n&amp;\\text{mask} = \\mathbb{1}[\\mathrm{count}(j) \\le C\\cdot B\\cdot k/N]\\\\\n&amp;y = \\sum_{j\\in S} w_j E_j(x)\\cdot \\text{mask}_j\n\\end{aligned}$$</div>\n<p>链路里每一步都引入不确定性：TopK 的输出集合随 token 变化，count(j) 随批内容变化，mask 随前两者变化。旧栈的 kernel 选择、tile 配置、通信切分全部在“形状已知”的前提下预调，这里每一步都要么在线重选、要么按最坏情况预留——前者增加调度开销，后者浪费算力。这就是“非改不可”的技术含义：不是换一个更快的 kernel，而是换一套能容纳动态形状的推理栈组织方式。</p>\n<p>具体代价可以定性描述：路由偏斜时，最忙设备的 GEMM 队列长度可达平均值的数倍，该设备的完成时间决定整层完成时间，其余设备的 SM 在此期间闲置；All-to-All 的尾延迟同理，由收发量最大的那一对设备决定。容量因子过小则丢弃 token，被丢弃 token 在该层的专家计算被整段跳过，残差直通，生成质量以不可控的方式退化——这不是精度问题，是结构性信息丢失。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-5\">五 · 论文给出的机制，以及它没有给出的</h3>\n<p>论文的核心机制是把每层前馈替换为 N 个结构相同的专家 FFN，路由器是一个小线性层，输出 N 维 logits 后取 top-k，输出按门控权重加权求和：</p>\n<div class=\"formula\">$$y_i=\\sum_{j\\in\\mathrm{TopK}(g_i)}\\mathrm{softmax}(g_i)_j\\,E_j(x_i)$$</div>\n<p>训练侧用负载均衡辅助损失约束利用率，以每专家实际接收 token 比例 f_j 与路由器平均概率 P_j 的乘积求和：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{aux}}=\\alpha\\sum_{j=1}^{N}f_j\\,P_j$$</div>\n<p>推理侧用容量因子截断每专家 token 数，超出部分掩码丢弃。这三件事——top-k 路由、辅助损失、容量因子——构成了论文对推理栈的全部结构性输入。它把“总参数与每 token 计算量解耦”这件事做成了机制，但没有给出部署所需的数字：专家数、隐藏维、层数、辅助损失系数 α、top-k 取值、容量因子取值，材料中均无具体数值。这意味着任何部署都必须把这些当作可调旋钮，而不是照抄的超参。</p>\n<p>对 Blackwell 档位的工程含义是明确的：分组 GEMM 的形状分布决定 tcgen05 与 TMEM 的利用率，路由张量与分组索引决定 All-to-All 的通信量，容量掩码决定丢弃率与质量折中。低精度权重部署（NVFP4/FP8）下，路由打分与门控权重的数值稳定性需要单独验证——材料未给出量化方案，不能从给定事实外推低精度收益。KV cache 策略同样未给出，长上下文场景需单独评估压缩与分页对显存的影响，并与专家权重共同纳入容量规划。</p>\n<p>论文留下的最大工程缺口是容量因子的静态性：它是阈值，不随实时路由分布自适应。偏斜流量下，要么丢 token，要么预留算力空转，二者必居其一。后续部署要围绕这个缺口做联合调优——监控每专家 token 计数、容量丢弃率、All-to-All 时延与分组 GEMM 形状分布，把容量因子与 top-k 作为运行时旋钮，按 SLO 违约率与丢弃率联动调整。这不是论文能回答的问题，是推理栈必须自己回答的问题。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-6\">六 · 落在具体机制上的判断</h3>\n<p>把这条链路拆到最细，真正的成本中心不是路由打分那个小线性层——它的 FLOPs 相对专家 FFN 可以忽略——而是分组 GEMM 的 M 维分布与 All-to-All 的收发量分布。这两个分布都由路由决定，而路由是离散、不可微、逐层独立的。工程判断因此落在三处：其一，容量因子必须与实时丢弃率联动，静态常量在偏斜流量下必然同时产生丢弃与空转；其二，分组 GEMM 的 tile 配置要按形状分布在线选择，而不是按平均形状预调，否则尾延迟由最瘦的那个专家 GEMM 决定；其三，All-to-All 的切分要按每专家 token 计数加权，而不是按设备数均分，否则最忙设备的排队时间直接进入整层关键路径。这三条都不是论文给的，是论文把问题推到台面上之后，推理栈必须补上的机制。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-7\">七 · 路由偏斜下的容量截断：旧方案在在线服务里的失效边界</h3>\n<p>考虑一个在线对话服务：请求变长、并发度随流量波动，SLO 以首 token 延迟与每 token 间隔衡量。在 Mixtral 这类稀疏专家模型进入推理栈之前，主流做法是把每层前馈当作一个稠密 GEMM 处理——批内所有 token 走同一组权重，kernel 形状由批大小与隐藏维唯一确定，调度器只需按显存与算力反推批大小。这条路径的边界非常清晰：每 token 计算量随参数量线性增长，吞吐与显存容量同时被锁死；扩容只能靠加卡，而加卡又受限于单层 GEMM 的并行切分效率。稠密方案的失效条件不是“模型太大”，而是“参数量增长必须等比例换取算力”，在给定功耗与显存预算下没有第二条曲线可走。</p>\n<p>MoE 把这条曲线掰开了：每 token 只激活 top-k 个专家，计算量由 k 与专家 FFN 规模决定，而非总参数量。但代价立刻转移到系统侧。设批内 B 个 token 进入某层，路由器输出 B×N 打分矩阵，取 top-k 后得到 B×k 的专家编号与门控权重；系统按容量因子 C 计算每专家上限，超出部分被掩码丢弃并跳过该层专家计算。于是每专家的实际 token 数 n_j 是随机变量，分组 GEMM 的 M 维即 n_j，形状随路由分布逐层抖动。稠密方案里“一个批一个形状”的确定性消失了，kernel 利用率不再由批大小决定，而由路由分布的偏斜程度决定。</p>\n<div class=\"formula\">$$\\text{drop}_j=\\max\\left(0,\\;n_j-\\left\\lceil C\\cdot\\frac{Bk}{N}\\right\\rceil\\right),\\qquad \\text{idle}_j=\\left\\lceil C\\cdot\\frac{Bk}{N}\\right\\rceil-n_j$$</div>\n<p>这两个量同时出现，就是旧方案最典型的失效现场：偏斜流量下，热门专家排队、冷门专家空转，容量因子取小则丢 token 影响生成质量，取大则显存与算力浪费。更麻烦的是容量因子是静态阈值，不随实时路由分布自适应，运维只能按最坏偏斜预留容量。专家并行把问题再放大一层：token 需经 All-to-All 发往持有对应专家的设备再送回，通信量与路由分布相关，最忙设备的排队时间直接变成尾延迟；而分组 GEMM 的 M 维抖动让 kernel 启动开销与 tile 利用率不稳，平均吞吐好看、P99 却违约。显存侧同样没有免费午餐——全部专家权重必须常驻，容量规划要同时计入专家权重、KV cache 与路由中间张量，总参数量远大于激活参数量这一事实在显存账本上不会因为稀疏而打折。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>稠密前馈方案</th><th>top-k 专家方案的边界</th></tr></thead><tbody><tr><td>GEMM 形状</td><td>由批大小唯一确定</td><td>由每专家 token 数决定，逐层抖动</td></tr><tr><td>负载分布</td><td>批内均匀</td><td>路由偏斜导致设备空转与排队并存</td></tr><tr><td>容量决策</td><td>批大小即容量</td><td>容量因子截断，丢弃率随偏斜上升</td></tr><tr><td>通信</td><td>无 token 交换</td><td>专家并行 All-to-All，尾延迟放大</td></tr></tbody></table>\n<p>所以“非改不可”的不是模型结构本身，而是推理栈对不确定性的处理方式：稠密栈把批当作调度单位，MoE 栈必须把“每专家 token 计数”当作一等监控指标，把容量因子、top-k 与专家并行度当作联动旋钮，并按 SLO 违约率与丢弃率反推批大小与并发度。材料未给出量化方案与 KV 压缩细节，低精度下路由打分与门控权重的数值行为需另行验证；在这条链路上，任何只报告平均吞吐而忽略分组 GEMM 形状抖动与 All-to-All 尾延迟的容量规划，都会系统性低估违约风险。</p>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-8\">八 · 从请求形态到每层 token 计数：可核查的测量口径</h3>\n<p>讨论 Mixtral 推理负载，第一步不是看 QPS，而是把外部请求形态翻译成每层路由的 token 总数。给定批内序列长度集合 $\\{L_1,\\dots,L_B\\}$，某层进入路由器的 token 数为 $T=\\sum_{i=1}^{B}L_i$（预填阶段）或 $T=B$（解码阶段每步）。这两个数相差一到三个数量级，决定了分组 GEMM 的 M 维量级，也决定了 All-to-All 是\"小包高频\"还是\"大包低频\"。测量口径必须把预填与解码分开记录，否则平均值会把两种截然不同的负载形态搅在一起，掩盖真正的尾延迟来源。</p>\n<p>可核查的最小采集集是：每层每专家的 token 计数直方图（不是均值）、容量丢弃率、分组 GEMM 的 M 维分布（P50/P99/最大值）、All-to-All 单次时延分布、以及首 token 延迟与每 token 间隔两个 SLO 指标。这些量必须按预填/解码、按请求长度分桶记录。工程上常见的错误是只报\"平均吞吐 tokens/s\"，这个数字对 MoE 几乎没有诊断价值——它无法区分是分组 GEMM 形状抖动、还是最忙专家排队、还是 All-to-All 阻塞造成的退化。</p>\n<p>输入长度分布直接塑造方案。短请求为主的负载（对话、分类）解码步占比高，每步 $T=B$ 很小，分组 GEMM 的 M 维可能只有几十，kernel 利用率低、启动开销占比高，此时提高批大小是主要手段，但批大小受 KV cache 显存约束。长上下文请求（文档问答、代码库分析）预填阶段 $T$ 巨大，路由分布在大 token 数下趋于均衡，分组 GEMM 形状稳定，但 KV cache 占用按 $L$ 线性增长，与全部专家权重争夺显存。同一个部署要同时服务两类请求时，容量规划必须按两类负载的混合比例反推，而不是按单一平均长度。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-9\">九 · 并发、批大小与容量因子的三角约束</h3>\n<p>容量因子 $C$ 把每专家可接收 token 上限写死为 $\\lceil C\\cdot T\\cdot k/N\\rceil$，其中 $N$ 为专家数、$k$ 为 top-k。这个式子揭示了三角约束：批大小 $B$ 与序列长度决定 $T$，$T$ 与 $C$ 共同决定每专家上限，而上限又反过来限制有效批大小——因为超出上限的 token 被掩码丢弃，等于这批请求里有部分 token 没被计算。丢弃率 $\\delta$ 是路由偏斜与 $C$ 的函数，偏斜越大、$C$ 越小，$\\delta$ 越高。质量损失与吞吐收益就在这条曲线上滑动。</p>\n<div class=\"formula\">$$\\text{每专家上限}=C\\cdot\\frac{T\\cdot k}{N},\\qquad \\delta=\\frac{\\sum_j\\max(0,\\,n_j-\\text{上限})}{T\\cdot k}$$</div>\n<p>这里的 $n_j$ 是第 $j$ 个专家实际收到的 token 数。测量 $\\delta$ 必须按层记录，因为浅层与深层的路由分布偏斜程度不同，聚合到模型级的单一丢弃率会掩盖某几层的严重丢弃。工程判断是：当 $\\delta$ 在 P99 请求上超过可接受阈值时，优先调大 $C$ 而不是调大批大小——调大 $B$ 会同步放大 $T$ 与偏斜的绝对量，可能让 $\\delta$ 更糟；调大 $C$ 只放松上限，代价是显存中路由中间张量与分组缓冲变大。</p>\n<p>具体例子：一个以短对话为主的在线服务，$B$ 设为较大值以摊薄解码步的 kernel 启动开销，但每步 $T=B$ 小、路由在少量 token 上抽样噪声大，个别专家可能一步收到远超均值的 token 数，触发丢弃。此时把 $C$ 从紧值放宽，丢弃率下降但每步分组 GEMM 的最大 M 维上升，最忙设备的排队时间变长，每 token 间隔的 P99 恶化。这就是\"方案反过来限制负载\"的典型：容量因子与批大小的选择改变了系统能承受的请求形态，部署方不得不对入口做长度分桶或并发限流。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-10\">十 · 尾延迟的三个来源与各自的测量方法</h3>\n<p>MoE 推理的尾延迟不是单一来源，至少三条链路各自贡献：其一，分组 GEMM 形状抖动——M 维随路由动态变化，最忙专家的 M 维可能是均值的数倍，该设备的 GEMM 时间成为该层的关键路径；其二，All-to-All 通信——token 需发往持有目标专家的设备再送回，通信量与路由分布相关，偏斜流量让某些链路的字节数超均值；其三，容量丢弃后的残差路径——被丢弃 token 该层输出为零只保留残差，虽然省了计算，但若丢弃集中在少数请求上，这些请求的生成质量下降会以重试或更长输出的形式反馈到负载上。</p>\n<p>测量方法必须能把三者拆开。对分组 GEMM，记录每层每设备实际执行的 M 维，取 P99 与最大值之比作为抖动指标；对 All-to-All，记录每次集合通信的字节数与等待时间，按源-目的设备对分组；对丢弃，记录每请求的累计丢弃 token 数而非全局平均。只有这三组分布同时拿到，才能判断一次 SLO 违约是形状抖动、通信阻塞还是丢弃引发的质量退化。仅报平均吞吐的系统在这三处全是盲区。</p>\n<p>工程上的直接推论：SLO 应以每 token 间隔的 P99 而非均值定义，因为尾延迟由最忙设备决定，而最忙设备由路由偏斜决定，偏斜又是批内请求内容决定的随机量。容量规划要按\"最忙专家承载上限\"而非\"平均每专家 token 数\"做显存与算力预算，否则在偏斜流量下必然违约。这与稠密模型按平均 FLOPs 规划的思路根本不同。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-11\">十一 · 负载如何反向塑造方案：入口整形与运行时旋钮</h3>\n<p>既然路由偏斜不可控，系统设计就把控制点前移到入口。常见做法是按序列长度分桶：短请求进小批、长请求进大批，避免同一批内长度方差过大导致 $T$ 的构成不稳定；对预填与解码分池调度，预填池追求大 $T$ 下的分组 GEMM 效率，解码池追求低延迟与小批。分桶的代价是调度复杂度与可能的批利用率下降，但换来的是分组 GEMM 形状分布收窄、尾延迟可预测。这是\"负载塑造方案\"的直接体现：不是让 kernel 适应任意负载，而是让负载适应 kernel 的形状偏好。</p>\n<p>运行时旋钮至少有三个：容量因子 $C$、top-k 与专家并行度。$C$ 调丢弃率与显存；top-k 在材料中作为模型结构给定，部署时通常不改，但它决定了每 token 激活计算量与 All-to-All 的 token 副本数——$k$ 越大，发往不同设备的 token 份数越多，通信量按 $k$ 放大；专家并行度决定每设备承载的专家数与 All-to-All 的跳数，并行度越高单设备专家越少、显存压力越小，但通信轮次与延迟上升。三者的联合调整必须挂在 SLO 违约率与丢弃率的反馈环上，而不是离线定死。</p>\n<p>具体例子：一个混合负载服务在高峰期观测到解码池的每 token 间隔 P99 超标，同时预填池的分组 GEMM 利用率正常。诊断路径是查解码池每层最忙专家的 M 维分布——若 P99 远超均值，说明小批下路由抽样噪声导致偏斜，解法是适度增大解码批或放宽 $C$；若 M 维分布正常而 All-to-All 等待时间尖峰，则是通信拓扑或并行度问题，解法是调整专家放置而非动批大小。两种诊断指向完全不同的旋钮，这正是分开测量三组分布的价值。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-12\">十二 · 显存预算里的三方争夺与可核查的容量口径</h3>\n<p>容量规划在 MoE 上比稠密模型多一项：全部专家权重必须常驻，即使每 token 只激活 $k$ 个。显存预算由三块构成——专家权重（与总参数量成正比，与激活参数量无关）、KV cache（与批内序列总长成正比）、路由中间张量与分组缓冲（与 $T\\cdot k$ 及 $C$ 成正比）。这三块的相对大小随负载形态变化：长上下文请求让 KV cache 成为主导，短请求高并发让路由中间张量占比上升，而专家权重是固定底噪。可核查的口径是按请求长度分桶，分别记录三块的实际占用峰值，而不是报一个模型级平均值。</p>\n<p>这里有一个方案反过来限制负载的硬约束：专家权重固定占用意味着可用于 KV cache 的显存上限被锁死，进而锁死了最大批内序列总长，也就锁死了能同时服务的并发请求数。当入口负载超过这个上限时，系统只能排队或拒绝，SLO 违约从延迟问题变成容量问题。工程判断是：在专家权重无法压缩（材料未给出量化方案）的前提下，KV cache 的分页与压缩是唯一能放松该约束的手段，而其效果必须单独测量，不能从稠密模型的经验外推。</p>\n<p>测量口径上还要区分\"名义容量\"与\"有效容量\"：名义上显存能装下的批大小，在实际路由偏斜下会因为最忙专家的分组缓冲膨胀而装不下。有效容量应按 P99 路由偏斜下的峰值占用计算，而非按均匀分布估算。这个差额在偏斜流量下就是违约的来源，也是容量规划必须留出的余量。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-13\">十三 · 失败模式的可观测信号与判断准则</h3>\n<p>把容量因子当固定常量是首要失败模式：流量偏斜时同时出现 token 丢弃与设备空转——丢弃发生在最忙专家，空转发生在最闲专家，两者在同一层同一时刻并存，平均利用率看起来正常。可观测信号是每专家 token 计数的方差与丢弃率的联合分布：方差大且丢弃率高，说明 $C$ 太紧；方差大而丢弃率低，说明 $C$ 太松、算力浪费。这个二维信号比任何单一指标都能定位问题。</p>\n<p>第二个失败模式是只报平均吞吐而忽略形状抖动与 All-to-All 尾延迟，导致 SLO 违约被低估。判断准则是：若分组 GEMM 的 M 维 P99/均值比超过某阈值且每 token 间隔 P99 同步恶化，则吞吐数字不可信作为容量依据。第三个失败模式是在缺少量化与 KV 策略材料时引用低精度收益——材料明确未给出 NVFP4/FP8 下路由打分与门控权重的数值行为，任何关于低精度吞吐提升的陈述都属无依据外推，应标注未给出而非估算。</p>\n<p>最终落在工程判断上：Mixtral 推理的负载形态不是外部给定常量，而是被容量因子、批策略与并行拓扑共同塑造的内生变量。可核查的测量必须按预填/解码、按请求长度分桶、按层记录每专家 token 计数与分组 GEMM 形状分布，并同时采集丢弃率与 All-to-All 时延。只有这三组分布在手，容量因子与批大小的联动调整才有依据；否则调参只是在平均值上做盲目的取舍，尾延迟与质量损失会在偏斜流量下同时爆发。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-14\">十四 · 负载形态如何反过来锁死容量因子与并行拓扑</h3>\n<p>在 Mixtral 这类 top-k 路由结构上，请求形态不是外部噪声，而是直接写进分组 GEMM 的 M 维。设某层批内 token 总数为 <span class=\"inline-math\">B</span>、专家数为 <span class=\"inline-math\">N</span>、容量因子为 <span class=\"inline-math\">C</span>，则每专家上限为 <span class=\"inline-math\">⌈C·B·k/N⌉</span>，而实际进入第 <span class=\"inline-math\">j</span> 个专家的 token 数 <span class=\"inline-math\">m_j</span> 由路由分布决定。丢弃率可写成 <span class=\"inline-math\">D=1−Σ_j min(m_j, ⌈C·B·k/N⌉)/(B·k)</span>。这个式子的工程含义是：输入长度分布越重尾、批内语义越集中，<span class=\"inline-math\">m_j</span> 的方差越大，<span class=\"inline-math\">D</span> 与最忙设备的排队时间同时上升。长上下文请求把 <span class=\"inline-math\">B</span> 抬高的同时放大 KV cache 占用，容量规划必须把专家权重、KV 分页与路由中间张量放在同一张显存预算表里算，否则调大 <span class=\"inline-math\">C</span> 换来的只是显存溢出而非吞吐。</p>\n<p>测量口径要可核查，就不能只报平均吞吐。至少采集四类量：每专家 token 计数的分位数（p50/p99 之比即偏斜度）、容量丢弃率 <span class=\"inline-math\">D</span>、All-to-All 单次时延的 p99、以及分组 GEMM 的 M 维直方图。首 token 延迟与每 token 间隔应分桶按输入长度报告，因为尾延迟违约几乎总来自最忙专家所在设备的排队，而非全局平均。<table class=\"mini\"><thead><tr><th>观测量</th><th>失效信号</th><th>系统代价</th></tr></thead><tbody><tr><td>专家 token 计数 p99/p50</td><td>偏斜度随并发升高</td><td>设备空转与排队并存</td></tr><tr><td>丢弃率 D</td><td>随 C 下调陡增</td><td>生成质量下降</td></tr><tr><td>All-to-All p99</td><td>与路由偏斜同向</td><td>尾延迟违约</td></tr><tr><td>分组 GEMM M 直方图</td><td>小 M 桶占比升高</td><td>kernel 利用率塌陷</td></tr></tbody></table></p>\n<p>方案反过来限制负载的机制在于容量因子是静态阈值：它无法随实时路由分布自适应，偏斜流量下要么丢 token 要么浪费算力。工程判断是，把 <span class=\"inline-math\">C</span> 与 top-k 作为运行时旋钮，按丢弃率与 SLO 违约率联动调整，而不是在部署时定死；同时用专家并行度匹配专家数以压低 All-to-All 跳数。若只报告平均吞吐而忽略形状抖动与通信尾延迟，会系统性低估违约风险——这是该方案最典型的边界失效条件。</p>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-15\">十五 · 路由张量与分组 GEMM 的 kernel 形态</h3>\n<p>Mixtral 的前馈子层被替换为 N 个同构专家 FFN，路由器是一个小线性层，输出 B×N 的打分矩阵后取 top-k。推理时真正决定 kernel 形态的不是 N，而是三个张量：B×k 的专家编号、B×k 的门控权重、以及按专家编号稳定排序后得到的分组索引。分组 GEMM 的 M 维等于某专家实际收到的 token 数，K 与 N 维是专家 FFN 的隐藏维，因此每个专家的 GEMM 是一个形状随路由动态变化的瘦长矩阵乘。Blackwell 上的核心 kernel 不是单个稠密 GEMM，而是「排序—分段—逐专家 GEMM—散射」这条链上的融合算子：把重排、门控加权与散射尽量压进同一个 kernel，减少中间张量往返 HBM 的次数。</p>\n<p>代价首先落在形状抖动上。设批内 B 个 token、top-k=k、专家数 N，第 j 个专家收到的 token 数为 m_j，则</p>\n<div class=\"formula\">$$m_j=\\sum_{i=1}^{B}\\mathbb{1}\\left[j\\in\\mathrm{TopK}(g_i)\\right],\\qquad \\sum_{j=1}^{N}m_j=B\\cdot k$$</div>\n<p>逐项解释：第一个求和是对批内所有 token 的指示函数累加，统计有多少 token 把专家 j 选进 top-k；第二个等式说明所有专家的 token 数之和恒等于 B·k，与路由分布无关。推论是：路由越偏斜，max_j m_j 越接近 B·k，最忙设备的 GEMM M 维越大，而其余专家的 M 维趋近于零，kernel 启动开销与尾延迟同时上升。工程上，m_j 的方差直接决定分组 GEMM 的有效利用率，容量因子 C 的作用就是把 m_j 截断到上限 ⌈C·B·k/N⌉，超出部分掩码丢弃。丢弃率随偏斜上升，这是质量与吞吐之间唯一显式的旋钮。</p>\n<p>具体例子：一个解码步 B=512、k=2、N=8，若路由均匀则每个专家约 128 个 token，8 个 GEMM 的 M 维整齐；若路由塌缩到 3 个专家，则最忙专家可能收到数百 token，其余 5 个专家 M 维为 0 或个位数，此时 5 次 kernel 启动纯属开销。Blackwell 的 tcgen05 指令集支持在单个 CTA 内发起异步 MMA，配合分组索引可以把「M 维过小则跳过」做成 kernel 内的分支，而不是在 host 侧逐专家 launch，这是把形状抖动从调度层下沉到 kernel 层的关键手段。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-16\">十六 · 数据类型：FP16/BF16 到 FP8 再到 NVFP4</h3>\n<p>专家权重占显存的大头，总参数量远大于激活参数量，因此低精度部署的第一收益是容量而非算力。BF16 与 FP16 在 Blackwell 上都是原生 MMA 输入类型，动态范围上 BF16 的 8 位指数更适合门控权重与路由 logits 这类跨层数值跨度大的张量；FP16 的 10 位尾数在专家 FFN 的激活上精度更细但更易溢出。FP8 分 E4M3 与 E5M2 两种编码，前者尾数多、适合权重与激活，后者指数多、适合梯度类张量；推理侧通常权重与激活都用 E4M3，配合 per-tensor 或 per-channel 缩放因子。NVFP4 是 4 位浮点加块级缩放（block scaling）的格式，尾数极短，必须靠每若干元素共享一个缩放因子来恢复动态范围，其收益是把专家权重显存压到 BF16 的四分之一量级，代价是缩放因子的元数据开销与反量化指令。</p>\n<p>低精度对 MoE 的特殊风险在路由链路上。路由器输出 N 维 logits 后做 softmax 取 top-k，门控权重是 softmax 的概率值，量级在 0 到 1 之间且分布尖锐；若把门控权重压到 FP4，相邻专家的概率差会被量化台阶吞掉，top-k 的选择可能翻转，进而改变分组索引与 GEMM 形状。工程判断是：路由打分与门控加权保持在 BF16 或 FP16，只对专家 FFN 的权重与中间激活做 FP8/NVFP4，这是把数值风险隔离在计算密集段、把选择精度留在控制段的常规做法。材料未给出 Mixtral 的量化方案，低精度下路由行为的稳定性需另行验证，不能从论文外推。</p>\n<p>代价量化：以专家权重为主体，BF16 下每参数 2 字节，FP8 下 1 字节，NVFP4 下约 0.5 字节加缩放元数据。显存节省直接转化为可容纳的 KV cache 与更大批大小，而批大小又反过来改善分组 GEMM 的 M 维、降低形状抖动的相对影响——低精度与吞吐之间不是简单的算力换算，而是通过批大小这条链路耦合。反量化本身要花指令周期，若在 GEMM 前逐块反量化到 BF16 再进 MMA，则省了显存没省带宽；Blackwell 的第五代 Tensor Core 支持低精度输入直接进 MMA、在累加器内以更高精度求和，才是把带宽收益兑现的路径。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-17\">十七 · 累加精度与误差传播</h3>\n<p>MMA 的输入精度与累加精度是两件事。分组 GEMM 的 K 维是专家 FFN 的隐藏维，K 很大，若累加器也用低精度，误差随 K 线性累积；因此硬件路径通常是低精度乘、高精度加。设单次乘法的相对误差为 ε，K 项求和的误差上界近似为</p>\n<div class=\"formula\">$$\\left|\\hat{s}-s\\right|\\lesssim \\varepsilon\\sum_{k=1}^{K}\\left|a_k b_k\\right|+\\mathcal{O}\\left(\\varepsilon^2\\right)$$</div>\n<p>解释：第一项是逐项乘积误差的绝对值和，说明误差不取决于结果的大小而取决于乘积累积的绝对值之和，即存在抵消时相对误差会被放大；第二项是二阶小量。对 MoE 的推论是：专家 FFN 中间激活若动态范围大（不同 token 的激活幅度差异大），低精度累加的误差在少数大幅值 token 上集中，表现为这些 token 的输出偏移，而路由权重又把这些偏移按门控概率加权求和，误差沿残差流逐层叠加。累加器保持 FP32 是抑制这条链的基线手段，tcgen05 的 MMA 在累加器侧提供高精度路径，使 FP8/NVFP4 输入不必以累加精度为代价。</p>\n<p>具体例子：某层某 token 被两个专家选中，门控权重分别为 0.7 与 0.3，若两个专家的输出各自带有方向相反的量化误差，加权求和会部分抵消；但若权重本身也被量化，抵消关系被破坏，误差转为系统性偏移。这解释了为什么门控加权求和这一段通常单独用 BF16 或 FP32 完成，而不并进低精度 GEMM 的 epilogue。代价是 epilogue 多一次精度转换与一次散射写回，带宽开销约为 B×k×hidden 量级的读写，相对于专家权重的读取是小头，但对尾延迟有贡献，因为它在关键路径上串行于 GEMM 之后。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-18\">十八 · Blackwell 特性如何落到这条链上</h3>\n<p>tcgen05 是 Blackwell 的第五代 Tensor Core 指令族，核心变化是把 MMA 的发起与数据搬运解耦：MMA 由单个 CTA 异步发起，操作数从 Tensor Memory（TMEM）取，累加器也落在 TMEM 而非寄存器堆。对分组 GEMM 的意义有两层。第一层是形状：TMEM 的容量按 CTA 划分，一个 CTA 可以连续发起多个不同 M 维的 MMA 而不必重配流水线，正好匹配逐专家 GEMM 的变长 M；第二层是占用：累加器不占寄存器，寄存器压力让给索引计算与散射逻辑，使「排序—GEMM—散射」能融进更少的 kernel。</p>\n<p>2-SM MMA 指两个 SM 协作完成一次 MMA，把一块较大的 tile 拆分到两个 CTA 上，共享操作数读取。对 MoE 的适用场景是那些 m_j 较大的热门专家：单专家 M 维足够大时，2-SM 协作能提高单次 MMA 的吞吐并减少操作数重复读取；而对 m_j 很小的冷门专家，2-SM 协作的同步开销大于收益，应退回单 SM 路径。于是 kernel 内部需要按 m_j 分档选择 MMA 形态，这本身就是形状抖动的一种应对：把「大专家走 2-SM、小专家走单 SM、空专家跳过」做成运行时分派，而不是靠容量因子把所有专家压成同一形状。</p>\n<p>代价侧写：TMEM 容量有限，同时驻留的累加器 tile 数受限，若一个 CTA 要顺序处理多个专家，必须在专家之间做 TMEM 的换入换出，这部分延迟与专家数成正比；2-SM MMA 的跨 SM 同步在专家边界处引入固定开销，热门专家越集中，这部分开销越值得付。功耗上，低精度 MMA 的单位算力能耗低于 BF16，但反量化与缩放因子读取是额外的数据通路活动，净收益取决于算术强度——分组 GEMM 的 M 维越小，算术强度越低，低精度的功耗优势越容易被数据搬运吃掉。这与第一部分讲的负载形态直接相关：短请求、低并发的批，M 维天然小，低精度 kernel 的收益被摊薄。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-19\">十九 · 融合边界与工程判断</h3>\n<p>把这条链拆成几个 kernel 是一个显式的设计选择。最粗的拆法是路由、排序、逐专家 GEMM、散射各一个 kernel，好处是每个 kernel 可独立调优、可独立观测，坏处是中间张量（分组索引、门控权重、专家输出）全部往返 HBM，带宽开销随 B·k·hidden 增长。最细的融法是把排序与散射融进 GEMM 的 prologue/epilogue，路由单独保留，因为 top-k 的离散选择不适合与 MMA 同 kernel。融合的边界应落在「数值精度切换点」上：路由与门控在 BF16/FP32，专家 GEMM 在 FP8/NVFP4 输入加 FP32 累加，epilogue 回到 BF16 做加权求和，精度转换点就是天然的 kernel 边界。</p>\n<p>一个可操作的伪代码思路是：按 m_j 排序专家，对 m_j 超过阈值的专家走 2-SM MMA 与 TMEM 常驻，对 m_j 低于阈值的专家合并成一个小批量走单 SM 路径，对 m_j 为零的专家直接跳过且不发起 MMA；容量掩码在排序阶段就写入索引，使被丢弃的 token 不进入任何 GEMM。这样做的代价是索引张量多一次遍历，收益是 kernel 启动次数从 N 降到有效专家数，且每次启动的 M 维尽量落在 MMA 的高效区间。</p>\n<p>工程判断落在三处：其一，容量因子必须与 kernel 分档联动，静态容量因子配合静态 kernel 形态会在偏斜流量下同时出现丢弃与空转；其二，低精度的收益要通过批大小兑现，而批大小受 KV cache 显存约束，因此量化决策与 KV 策略必须一起做，不能分开评估；其三，材料未给出 Mixtral 的量化与硬件档位细节，任何 FP8/NVFP4 的收益数字都属于外推，部署时应以分组 GEMM 的 M 维分布、每专家 token 计数与 All-to-All 时延作为观测面，先确认形状抖动是否已被 kernel 分档吸收，再谈精度档位的下调。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-20\">二十 · 分组 GEMM 的形状抖动与低精度累加的边界</h3>\n<p>MoE 推理的 kernel 效率不由总参数量决定，而由每专家实际收到的 token 数决定：分组 GEMM 的 M 维即该子集大小，随路由分布逐层、逐步变化。容量因子 C 给每专家设上限 <span>⌈C·B·k/N⌉</span>，实际 M 往往远小于上限，于是同一 kernel 在相邻解码步之间面对不同 tile 形状，Tensor Core 的 MMA 指令利用率随之抖动。Blackwell 上 tcgen05 与 2-SM MMA 要求成对的 SM 协同、操作数经 TMEM 中转，形状越碎，TMEM 分配与 MMA 流水启动开销占比越高；把 M 维对齐到 tile 边界（padding 到固定倍数）能稳定流水，代价是空算 tile 的算力浪费，这部分浪费与路由偏斜程度成正比。</p>\n<p>低精度侧的关键边界在累加而非乘法。以 NVFP4 为例，块缩放把权重与激活压到 4 位，乘积在 Tensor Core 内以更高位宽累加，误差主要来自块内动态范围被单一缩放因子压缩：<div class=\"formula\">$$\\hat{y}=\\sum_{j\\in\\mathrm{TopK}(g_i)}\\hat{s}_j\\,\\hat{E}_j(\\hat{x}),\\qquad \\hat{s}_j=\\mathrm{softmax}(\\hat{g}_i)_j$$</div>门控权重 ŝ_j 与专家输出 Ê_j 各自带量化误差，加权求和时误差不被平均掉——top-k 只取少数专家，误差直接进入残差流并逐层累积。路由打分 ĝ_i 本身若被量化，top-k 的边界 token 可能换专家，属于离散跳变而非平滑误差，无法用校准补偿。工程判断是：路由线性层与门控权重保持 FP16/BF16，专家 FFN 权重与激活才下探 FP8/NVFP4，累加保持 FP32；这条分界线的系统代价是路由张量显存与一次高精度小 GEMM 的延迟，相对于专家权重的显存节省可以接受。</p>\n<p>容量丢弃与低精度叠加会放大失效条件：被掩码丢弃的 token 该层输出为零，仅剩残差，若同时专家输出带量化偏差，两层叠加后残差流的数值分布偏移更难被后续层校正。监控应采集每专家 token 计数分布、分组 GEMM 实际 M 维直方图、容量丢弃率与门控权重的动态范围，用丢弃率与 M 维方差联动调整容量因子；只报平均吞吐会掩盖最忙设备的排队与空转设备的同时存在。</p>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-21\">二十一 · 显存账本的三条主线：专家权重、KV cache、路由中间张量</h3>\n<p>在 Blackwell 档位上给 Mixtral 这类稀疏专家模型做容量规划，第一件事不是问“模型多大”，而是把显存拆成三本互不重叠的账：常驻的专家权重、随序列与并发增长的 KV cache、以及每个解码步瞬时存在但形状随路由抖动的中间张量。三者性质完全不同——专家权重是静态且必须全量驻留（因为任何 token 都可能路由到任何专家），KV cache 是按层按 token 线性增长的动态占用，路由中间张量则是每层、每步都要重新分配的短命缓冲。把这三者混成一个“总显存”数字，是容量规划最常见的错误来源。</p>\n<p>专家权重的账本逻辑由结构直接决定：每层前馈被替换为 N 个结构相同的专家 FFN，路由器只是一个小线性层。设隐藏维为 d、专家 FFN 中间维为 d_ff、层数为 L、专家数为 N，则单层专家权重参数量约为 N·(3·d·d_ff)（gate/up/down 三个投影），全模型专家权重为：</p>\n<div class=\"formula\">$$M_{\\text{exp}} \\approx L \\cdot N \\cdot 3 \\cdot d \\cdot d_{ff} \\cdot b_w$$</div>\n<p>其中 b_w 是每参数字节数。这条式子说明一个关键事实：总参数量远大于激活参数量，但显存必须按总参数量付账。激活计算量只由 top-k 与单专家规模决定，显存却由 N 决定——这是 MoE 推理“算得省、存得贵”的结构性不对称。在 NVFP4（4 bit 权重）下 b_w≈0.5，FP8 下 b_w=1，同一模型的权重占用相差一倍，直接决定单卡能否放下全部专家、还是必须走专家并行。</p>\n<p>KV cache 的账本与专家权重正交：它按层、按序列 token 数、按并发批增长。设批内总 token 数为 T_b、KV 头数为 h_kv、每头维数为 d_h、层数为 L、每元素字节为 b_kv，则：</p>\n<div class=\"formula\">$$M_{\\text{kv}} = 2 \\cdot L \\cdot T_b \\cdot h_{kv} \\cdot d_h \\cdot b_{kv}$$</div>\n<p>系数 2 来自 K 与 V 两份。注意这里用的是 KV 头数而非查询头数——若模型采用分组查询注意力，h_kv 远小于 h_q，KV 账本会显著缩小，这是长上下文场景下唯一不需要牺牲质量的压缩手段。工程代价很直接：T_b 翻倍，KV 占用翻倍，而专家权重一动不动；反过来，把权重压到 4 bit 省下的空间，可能被一条长上下文请求的 KV 增长迅速吃掉。</p>\n<p>第三本账是路由中间张量：每层 B×N 的打分矩阵、B×k 的专家编号与门控权重、按专家重排后的分组索引与容量掩码。这些张量尺寸小，但生命周期极短、每层都要重新分配，且其形状由路由分布决定。在连续批处理下，它们的分配/释放频率与批周转率同阶，是显存碎片与分配器压力的主要来源。具体例子：一个批在某一层路由后，某专家收到远超容量上限的 token，多出的 token 被掩码丢弃，这些被丢弃 token 的中间激活仍占着缓冲直到该层结束——账本上它们不计入有效计算，却实实在在占着显存。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-22\">二十二 · 带宽瓶颈的位置：权重流、KV 流与 All-to-All 流</h3>\n<p>解码阶段的算术强度极低：每生成一个 token，要把激活的专家权重从 HBM 读一遍，却只做一次矩阵向量乘。因此单 token 延迟的主项不是算力而是权重带宽。设激活专家数为 k、单专家权重字节为 w_e、HBM 有效带宽为 BW，则单层单 token 的权重读取时间下界为：</p>\n<div class=\"formula\">$$t_{\\text{layer}} \\gtrsim \\frac{k \\cdot w_e}{BW}$$</div>\n<p>这条下界解释了为什么 MoE 在解码时比同总参数稠密模型快：稠密模型每 token 要读全部权重，MoE 只读 k 个专家。但它也暴露了 MoE 的带宽账本另一面——权重总量大，若专家并行度不足、单卡要放下全部专家，则每卡 HBM 容量与带宽都被总参数量绑定，低精度权重成为必选项而非优化项。</p>\n<p>KV cache 的带宽账本在长上下文与高并发下会反超权重。每步解码要为批内所有 token 读一遍 KV，读取量为 2·L·T_b·h_kv·d_h·b_kv，与权重读取量同阶甚至更大。分页（paged KV）把 KV 切成固定大小的块，按需分配、按块索引，消除连续大块分配带来的外部碎片；代价是注意力核需要按块表做间接寻址，块表本身也占显存与带宽。压缩手段包括 KV 量化（降低 b_kv）、分组查询注意力（降低 h_kv）、以及跨请求的块复用（相同前缀共享 KV 块）。复用是最省的一档：前缀相同的请求在预填阶段只算一次 KV，后续请求直接挂到已有块上，省下的是预填算力与 KV 写入带宽，而非读取带宽。</p>\n<p>第三条流是专家并行的 All-to-All。token 按专家编号重排后发往持有对应专家的设备，算完再送回。通信量与批内 token 数、隐藏维、以及路由偏斜程度相关：偏斜越重，最忙设备排队越久，而其他设备的链路空转。在 NVLink 5 域内这尚可承受，跨节点则要经 NCCL 或 NIXL 走网络，尾延迟被放大。工程判断是：把 All-to-All 的通信量与分组 GEMM 的 M 维抖动一起看，二者共同决定单步的尾延迟，只看平均吞吐会系统性低估 SLO 违约率。</p>\n<p>具体例子：一个批在某一层路由后，专家 3 收到接近容量上限的 token，专家 11 只收到个位数 token。持有专家 3 的设备要做一个大 M 的分组 GEMM，持有专家 11 的设备几乎空转；反向 All-to-All 时，前者要回传大量结果，后者几乎不发。这一层的耗时由最忙设备决定，而显存账本上，空转设备的专家权重照样占着容量——负载不均同时浪费算力与显存。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-23\">二十三 · 可复算的显存预算：从符号到具体档位</h3>\n<p>把三本账合成一个可复算的预算式。给定部署档位（单卡容量 C、权重精度 b_w、KV 精度 b_kv），要回答的问题是：在给定并发与上下文长度下，单卡能放多少专家、能挂多少 token。预算式为：</p>\n<div class=\"formula\">$$M_{\\text{total}} = \\underbrace{\\frac{L \\cdot N \\cdot 3 \\cdot d \\cdot d_{ff} \\cdot b_w}{P_{\\text{exp}}}}_{\\text{本地专家权重}} + \\underbrace{2 L T_b h_{kv} d_h b_{kv}}_{\\text{KV cache}} + M_{\\text{route}} + M_{\\text{act}} \\le C \\cdot \\eta$$</div>\n<p>其中 P_exp 是专家并行度（每卡持有的专家份额），M_route 是路由中间张量与分组索引缓冲，M_act 是激活与临时 workspace，η 是留给碎片与运行时开销的安全系数。这个式子的用法是反推：先定 C 与 η，再定 b_w 与 b_kv，然后解出在给定 T_b 下允许的 P_exp，即最少需要几张卡。</p>\n<p>举一个符号化的复算例子（不引用材料外的具体数值，只演示结构）：设某配置下专家权重在 FP8 时占单卡容量的大头，把权重换成 NVFP4 后 b_w 减半，权重项直接减半，释放出的容量可以用于两件事——提高 T_b（挂更多并发或更长上下文），或降低 P_exp（减少卡数）。选择哪条路取决于瓶颈在带宽还是在容量：若解码延迟受权重带宽约束，降精度同时降低权重读取字节，直接改善 t_layer；若瓶颈在 KV 带宽，则释放出的容量应优先换 T_b，但 KV 读取量随之上升，延迟未必改善。这就是为什么“量化省显存”与“量化提吞吐”不能混为一谈——前者是容量账，后者要过带宽账。</p>\n<p>路由中间张量与激活的账本容易被忽略但不可省。分组 GEMM 的 workspace 随 M 维动态变化，容量因子越大、批越大，workspace 峰值越高；容量掩码与分组索引是每层都要重建的缓冲。工程上应把它们按峰值预留而非按均值预留，否则在路由偏斜的批上会出现瞬时 OOM——这类失败不体现在平均显存曲线上，只体现在尾部的分配失败。</p>\n<p>卸载（offload）是预算式的一个补充项而非替代项。把冷专家权重放到主机内存、按路由需要换入，等于把权重项从 C 挪到主机侧，代价是 PCIe 带宽成为新的 t_layer 下界：换入一个专家的时间远大于从 HBM 读它的时间。只有当路由分布高度集中、少数专家承载绝大多数 token 时，卸载才有正收益；路由越均衡，卸载的换入频率越高，收益越负。这与容量因子的取舍是同一个问题的两面。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-24\">二十四 · 分页、压缩与复用的组合策略</h3>\n<p>KV 侧的三项技术要组合使用而非单独评估。分页解决的是碎片：固定大小的块让不同长度的序列可以交错分配，块表记录逻辑块到物理块的映射，注意力核按块表 gather。压缩解决的是字节数：KV 量化把 b_kv 从 2 降到 1 甚至更低，代价是注意力打分的数值误差，需在长上下文上单独验证。复用解决的是重复计算：相同前缀的请求共享已算好的 KV 块，预填阶段只算增量。三者叠加后的账本是：</p>\n<div class=\"formula\">$$M_{\\text{kv}} = 2 L h_{kv} d_h b_{kv} \\cdot \\sum_{r \\in \\text{batch}} \\big(T_r - T_{\\text{shared},r}\\big) + M_{\\text{block-table}}$$</div>\n<p>其中 T_shared,r 是第 r 个请求可复用的前缀长度。复用项的收益随前缀重合度上升，在系统提示固定、多轮对话、或少样本提示场景下最明显；在请求彼此无关的开放域流量下收益趋零。工程判断是：复用不是免费的——块表本身占显存、块查找增加注意力核的间接寻址开销，前缀重合度低时净收益为负。</p>\n<p>分页与专家并行的交互值得单独一提。专家并行下，token 要跨设备搬运，KV cache 通常留在注意力所在设备上，而专家计算在另一设备上完成。这意味着 KV 的物理位置与专家的物理位置解耦：KV 账本按注意力并行度分摊，专家权重账本按专家并行度分摊，两套并行拓扑可能不同。容量规划时必须分别计算两条账，再在同一张卡的 C 上求和——这是分离式预填/解码架构下最容易被算错的地方。</p>\n<p>具体例子：一个多轮对话请求，系统提示占前缀的大部分。首轮预填算出该前缀的 KV 块并留在池中；后续轮次只对新增用户消息做预填，KV 账本上只增加增量部分。若此时另一路请求共享同一系统提示，它直接挂到同一批块上，预填算力与 KV 写入带宽都省下。但若两路请求的上下文在系统提示之后分叉，块表要支持写时复制或按块分裂，否则复用会污染彼此的 KV——这是分页实现里的经典取舍，代价是块管理与额外的块分配。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-25\">二十五 · 容量因子与显存账本的联动</h3>\n<p>容量因子不只是丢弃策略的旋钮，它同时是显存账本的旋钮。容量因子 C_f 决定每专家可接收的 token 上限，上限越高，分组 GEMM 的 M 维峰值越高，workspace 峰值越高；上限越低，丢弃率越高，但显存峰值越低。设每专家上限为 ⌈C_f · T_b / N⌉，则分组 GEMM 的 workspace 峰值近似正比于该上限乘以单 token 激活字节：</p>\n<div class=\"formula\">$$M_{\\text{ws}} \\propto \\left\\lceil C_f \\cdot \\frac{T_b}{N} \\right\\rceil \\cdot d \\cdot b_{\\text{act}}$$</div>\n<p>这条式子把容量因子从“质量与吞吐的折中”扩展为“质量、吞吐与显存的三方折中”。容量因子调大，丢弃率下降、质量改善，但 workspace 与分组 GEMM 的 M 维峰值上升，显存账本变紧、形状抖动加剧；调小则相反。工程上应把容量因子与批大小联动：批越大，单专家平均 token 数越高，同样的容量因子下丢弃率越低，但 workspace 峰值也越高。二者不是独立可调的。</p>\n<p>路由偏斜是这条联动里的扰动项。偏斜重时，少数专家接近上限而多数专家远低于均值，此时提高容量因子只让少数专家的 workspace 峰值上升，对多数专家的显存无影响，却显著降低丢弃率——这是偏斜流量下提高容量因子的正收益区间。反之，路由均衡时提高容量因子几乎不降低丢弃率（因为没人接近上限），只白白抬高 workspace 峰值。因此容量因子应随实测的路由偏斜度自适应，而非固定常量；固定常量在偏斜流量下会同时出现 token 丢弃与设备空转，在均衡流量下则浪费显存。</p>\n<p>监控项应覆盖三本账的实时状态：每专家 token 计数与容量丢弃率（路由账）、分组 GEMM 的 M 维分布（workspace 账）、KV 块分配率与块表大小（KV 账）、以及 All-to-All 时延分布（通信账）。只报平均吞吐会掩盖形状抖动与尾延迟；只报平均显存会掩盖瞬时分配失败。容量规划的最终判断落在具体机制上：把专家权重按总参数量付账、把 KV 按并发与上下文付账、把路由中间张量按峰值付账，三者相加再留出碎片余量，才是 Blackwell 档位上可复算、可监控、可随路由分布调整的显存预算。</p>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-26\">二十六 · 连续批处理与分组 GEMM 的形状抖动</h3>\n<p>Mixtral 的推理批不是稠密模型意义上的矩形批。一个解码步里，批内 B 个 token 各自经路由器取 top-k，形成 B×k 的专家编号与门控权重；按专家编号稳定排序后，第 j 个专家收到的 token 数 m_j 才是分组 GEMM 的 M 维。连续批处理（continuous batching）在每步迭代边界上增删请求，使 B 本身逐 step 变化，于是 m_j 同时受两个随机源驱动：批组成与路由分布。稠密模型的 GEMM 形状随批大小单调变化，可以靠 padding 到固定 tile 抹平；MoE 的形状抖动来自排序后的直方图，padding 只能对齐单个专家的 M 维，无法对齐跨专家的负载分布。</p>\n<p>工程上要把抖动压到可预测，调度器需要在组批时估计本步的路由直方图。一个可用的伪代码思路是：</p>\n<div class=\"formula\">$$\\hat{m}_j=\\sum_{i\\in\\mathcal{B}}\\mathbb{1}\\left[j\\in\\mathrm{TopK}(g_i)\\right],\\qquad \\mathrm{cost}\\approx\\sum_{j}\\left\\lceil \\hat{m}_j/T\\right\\rceil\\cdot T$$</div>\n<p>其中 T 是分组 GEMM 的 tile 高度。调度器以该代价函数而非 token 总数做组批决策，可以把“批里塞满但专家全挤在少数几个”的坏批排除掉。代价体现在两个方向：组批时多算一次路由打分（相对整层计算可忽略），换来的是 kernel 利用率稳定；若不做这步估计，最忙专家的 M 维可能数倍于平均值，其排队时间直接进入每 token 间隔的尾部分布。具体例子：一个 8 专家、top-2 的层，若某步 64 个 token 中有 40 个把同一专家选进 top-2，该专家的分组 GEMM 要跑 40 行而其余专家只有个位数行，整层的完成时间由这 40 行决定，其余设备的 SM 在该段时间空转。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-27\">二十七 · chunked prefill 与预填/解码混批的相互干扰</h3>\n<p>预填阶段一个请求的 token 数可达数千，若整块插入解码批，会让该 step 的 B 骤增、路由直方图被单个请求主导，解码请求的每 token 间隔出现尖峰。chunked prefill 把长预填切成固定大小的 chunk，逐 step 与解码 token 混批，使 B 的上界可控、路由分布不被单请求垄断。切分粒度是显式旋钮：chunk 太小则预填请求的首 token 延迟被拉长（需要更多 step 才能喂完），chunk 太大则解码侧尾延迟变差。</p>\n<p>MoE 特有的问题是混批时预填 token 与解码 token 共享同一套容量因子。容量因子按每专家 token 上限截断，预填 chunk 的 token 集中度高，容易把某些专家顶到上限，导致同批的解码 token 被掩码丢弃——解码 token 被丢弃意味着该 step 的输出质量直接受损，而预填 token 被丢弃只是延迟体现。因此混批调度应把容量预算按预填/解码分组隔离，或对解码 token 给予容量优先级。代价上，隔离预算会降低专家平均利用率、抬高单位 token 的显存带宽占用（专家权重读取次数增加），这是用吞吐换尾延迟与质量的典型取舍。具体例子：一个 2k token 的预填 chunk 与 32 个解码请求混批，若不做隔离，路由偏斜使两个专家达到容量上限，解码侧若干 token 在该层输出为零、仅剩残差，生成结果出现局部退化；隔离后预填 chunk 自身可能丢弃少量 token，但解码路径完整。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-28\">二十八 · 优先级、抢占与容量因子的联动</h3>\n<p>容量因子是静态阈值，无法随实时路由分布自适应，这是 Mixtral 推理侧最直接的局限。调度器能做的补偿是在请求维度引入优先级与抢占：当高优先级请求（短 SLO、交互式会话）到达时，抢占低优先级请求的批位置与 KV cache 页，把专家容量预算向高优先级批倾斜。抢占的代价不是免费的——被抢占请求的 KV cache 需要换出到主机内存或重算预填，重算路径会再次产生预填 token，反过来加剧路由偏斜。</p>\n<p>一个可操作的判断规则是把容量丢弃率作为抢占触发的观测量：</p>\n<div class=\"formula\">$$\\mathrm{drop}_j=\\max\\left(0,\\;m_j-C\\cdot\\frac{B\\cdot k}{N}\\right)\\Big/\\,m_j$$</div>\n<p>当某专家的 drop_j 超过阈值且该专家承载的是高优先级 token 时，触发对该批的重排或对低优先级请求的抢占，而不是简单接受丢弃。代价体现在显存与带宽：抢占需要保留被换出请求的 KV 页元数据，KV cache 的碎片化会抬高页表遍历开销；重算预填则重复消耗专家权重带宽。具体例子：交互式请求与离线批处理共享一个专家并行组，离线批的偏斜流量把两个专家打到容量上限，交互式请求的 token 开始被丢弃、首 token 延迟抖动；调度器按 drop_j 触发抢占离线批的一个 chunk，交互式请求恢复完整路径，代价是离线批的吞吐下降与该 chunk 的重算。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-29\">二十九 · 分离式预填/解码对 All-to-All 的重构</h3>\n<p>分离式（disaggregated）预填/解码把预填与解码放到不同实例组，KV cache 经高速互联从预填组传到解码组。对 MoE 而言，这一拆分的收益不止于消除混批干扰：预填组的批由长序列组成、路由直方图相对平滑（token 多、统计充分），解码组的批由大量短请求组成、路由偏斜更尖锐。两组各自按自己的分布调容量因子与专家并行度，比混在一起用一套参数更贴近实际。代价是 KV 传输占用互联带宽，且解码组需要为每个请求保留完整的专家权重副本——显存需容纳全部专家权重这一约束在两组上各算一遍，总显存占用上升。</p>\n<p>All-to-All 的通信量在分离架构下也发生变化：预填组每 step 处理的 token 数远大于解码组，其 All-to-All 是带宽密集型、可被 chunk 边界对齐成规则形状；解码组的 All-to-All 是延迟敏感型、每 step 只有少量 token 但 step 频繁，通信启动开销占比高。工程判断是：预填组用较大的 chunk 与较高的专家并行度摊薄通信，解码组用较低的并行度减少 All-to-All 跳数、把专家权重尽量放在本地。具体例子：解码组若把专家并行度从 8 降到 2，单次 All-to-All 的跳数与数据量下降，但每设备需容纳更多专家权重，显存压力上升；这一取舍需与 KV cache 占用一起做容量规划，而不是单独看通信时延。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-30\">三十 · 尾延迟的分解与可观测项</h3>\n<p>Mixtral 推理的尾延迟不是单一来源，压尾延迟的前提是把它拆开。可分解为四项：分组 GEMM 形状抖动导致的 kernel 利用率损失、All-to-All 中由最忙设备决定的排队时间、容量丢弃引发的重算或质量补救、以及 KV cache 换入换出。前两项与路由分布直接相关，后两项与调度策略相关。只报告平均吞吐会把这些全部掩盖——平均吞吐对偏斜不敏感，因为空转设备的空闲时间在平均里被摊平，而 SLO 违约恰恰发生在最忙设备决定的那一步。</p>\n<p>可观测项应至少包括：每专家 token 计数 m_j 的分布（用分位数而非均值）、容量丢弃率 drop_j、All-to-All 的单步时延分位数、分组 GEMM 的 M 维直方图。调度器以这些量做闭环：当 m_j 的高分位数持续超过容量上限，说明容量因子偏小或专家并行度与路由分布不匹配；当 All-to-All 时延分位数抬升而 GEMM 形状正常，说明瓶颈在互联而非计算。具体例子：某部署的平均吞吐稳定，但 p99 每 token 间隔出现周期性尖峰，观测发现尖峰与某专家的 m_j 高分位数同步，进一步定位到该专家的分组 GEMM 因 M 维超过 tile 整数倍而多跑一轮；把容量因子略微下调并把该专家的 token 分流到次选专家（调整 top-k 的门控阈值），尖峰消失，代价是少量 token 被丢弃、质量轻微下降。</p>\n<p>最终落在工程判断上：Mixtral 的调度不是“把批塞满”的问题，而是在路由直方图不可控的前提下，用 chunk 边界、容量预算隔离、优先级抢占与预填/解码分离四个旋钮，把尾延迟的来源逐项钉住。容量因子与 top-k 是运行时旋钮，其取值应由 drop_j 与 m_j 分位数的联合观测驱动，而不是按平均负载一次性设定；任何只报告平均吞吐而不披露分组 GEMM 形状分布与 All-to-All 分位时延的容量规划，都无法回答 SLO 违约发生在哪一步。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-31\">三十一 · 容量因子之外的调度边界：路由偏斜如何吃掉连续批处理的红利</h3>\n<p>连续批处理在 MoE 上的失效点不在批调度器本身，而在每层路由后形成的分组批次形状不可预测。稠密模型一个 decode step 的 GEMM 形状由批大小 B 唯一决定，调度器可以按 B 线性外推耗时；MoE 则先由路由器产出 B×N 打分矩阵，top-k 后每专家实际收到的 token 数 m_j 是随机变量，分组 GEMM 的 M 维等于 m_j，且受容量因子截断：m_j' = min(m_j, ⌈C·B·k/N⌉)。这意味着同一批大小下，最忙设备的 GEMM 规模可能数倍于平均值，而最闲设备接近空转。连续批处理把新请求插入正在执行的批以填满算力空隙，但在 MoE 上，插入的 token 会重新分配路由分布，使原本已排队的专家更忙、原本空闲的专家仍空闲——批调度器看到的“空隙”是设备级而非专家级的，填充动作对尾延迟的改善有限。工程判断是：MoE 的批调度必须以每专家 token 计数为反馈信号，而非仅以批大小或 KV 占用为信号；容量因子若固定为常量，偏斜流量下会同时出现丢弃与空转，这正是材料指出的失败模式。</p>\n<p>chunked prefill 在 MoE 上的代价被 All-to-All 放大。把长预填切成固定 token 数的 chunk 可以压低首 token 延迟并让 decode 请求插队，但每个 chunk 都要独立走一遍路由、重排、All-to-All、分组 GEMM、反向 All-to-All、散射的完整链路。设 chunk 大小为 S，专家并行度为 E，则每层每个 chunk 的 All-to-All 通信量正比于 S·k·d（d 为隐藏维），与 chunk 数成线性关系；chunk 切得越细，通信启动开销与 kernel launch 占比越高，分组 GEMM 的 M 维越小、越难打满 tensor core。更关键的是，chunk 边界处的路由分布彼此独立，多个小 chunk 的专家负载无法像一个大 chunk 那样在统计上互相平滑，偏斜反而更尖锐。因此 chunked prefill 的 chunk 大小在 MoE 上不是纯延迟旋钮，而是延迟、通信量与 GEMM 效率的三方折中：chunk 过小则 All-to-All 次数膨胀、GEMM 形状碎化；chunk 过大则 decode 请求被长预填阻塞，首 token 延迟与每 token 间隔同时恶化。</p>\n<p>优先级与抢占在 MoE 上的特殊约束是显存与路由中间张量双重占用。抢占一个 decode 请求需要换出其 KV cache，但 MoE 还额外持有路由张量、专家分组索引与容量掩码，这些中间张量按层生成、按批共享，抢占粒度若按请求而非按批，则被抢占请求的中间张量无法单独释放，只能随整批重算。分离式预填/解码把预填与解码放到不同实例，本可让预填侧专注大 chunk 的高 GEMM 效率、解码侧专注低延迟，但在 MoE 上两侧都要各自承载全部专家权重——显存需容纳全部专家权重这一事实不会因分离而减半，反而使专家权重的副本数随实例数上升。若采用专家并行把专家分散到多卡，则预填与解码两侧的 All-to-All 拓扑必须一致，跨实例的 token 交换会把 NVLink 域内的通信变成跨域通信，尾延迟来源从设备排队转为链路排队。容量规划须同时计入专家权重、KV cache 与路由中间张量，分离式部署在这三项上都做加法而非减法。</p>\n<p>尾延迟的压缩不能靠平均吞吐指标，而要对分组 GEMM 形状分布与 All-to-All 时延做分位数监控。可操作的手段有三：其一，按每专家 token 计数的实时分布动态调整容量因子，偏斜上升时放宽上限以避免丢弃、偏斜下降时收紧以节省显存与计算，把静态阈值变成闭环控制；其二，在专家并行拓扑上做负载感知的 token 重排，把同一专家的 token 尽量聚到同一设备以减少跨设备往返次数，代价是重排本身引入额外索引计算；其三，对最忙设备的排队时间设上限，超过即触发抢占或降级到丢弃策略，用质量换 SLO。这三者都以牺牲平均吞吐换取尾部分位数为代价，工程上应把 SLO 违约率与容量丢弃率作为联动旋钮，而非单独优化吞吐。材料未给出拓扑细节与量化方案，低精度下路由打分与门控权重的数值行为需另行验证，不能从稀疏结构直接外推 NVFP4/FP8 的收益。</p>\n<table class=\"mini\"><thead><tr><th>调度手段</th><th>主要收益</th><th>MoE 上的失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>连续批处理</td><td>填满设备算力空隙</td><td>空隙是设备级而非专家级，插入 token 加剧偏斜</td><td>分组 GEMM 形状抖动，尾延迟上升</td></tr><tr><td>chunked prefill</td><td>压低首 token 延迟</td><td>chunk 过小则 All-to-All 次数与 launch 开销膨胀</td><td>通信量随 chunk 数线性增长，GEMM 效率下降</td></tr><tr><td>优先级抢占</td><td>保障高优请求 SLO</td><td>中间张量按批共享，无法按请求单独释放</td><td>整批重算，KV 与路由张量双重换出</td></tr><tr><td>分离式预填/解码</td><td>两侧各自优化延迟与吞吐</td><td>专家权重副本随实例数上升，跨域 All-to-All</td><td>显存加法，链路排队取代设备排队</td></tr></tbody></table>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-32\">三十二 · 切分维度：TP 切的是矩阵，EP 切的是 token</h3>\n<p>Mixtral 的推理拓扑不能只用一个并行度描述。张量并行（TP）切分的是每个专家 FFN 内部的权重矩阵，每层做两次 All-Reduce 把分片的部分和拼回完整激活；专家并行（EP）切分的是专家本身，每张卡持有不相交的专家子集，token 必须被搬运到持有目标专家的设备上。这两者的通信语义完全不同：TP 的 All-Reduce 是固定形状、每层必发的集合通信，EP 的 All-to-All 是数据依赖、形状随路由分布波动的稀疏交换。流水并行（PP）沿层切分，代价是流水气泡与激活的跨阶段传递；数据并行（DP）复制全部专家权重、切分请求批次，代价是权重显存随副本数线性膨胀。对 Mixtral 这类总参数远大于激活参数的模型，DP 的显存代价最不可接受——每份副本都要装下全部专家，而每 token 只用到其中 k 个。因此生产部署的主轴通常是 EP 承担专家容量、TP 承担单专家内的计算宽度，PP 只在单机放不下时引入。</p>\n<p>用公式刻画单层通信量。设批内 token 数为 B，隐藏维为 H，top-k 为 k，专家并行度为 E，单精度字节数为 s。EP 下每层前向的 All-to-All 发送量为：</p>\n<div class=\"formula\">$$V_{\\text{a2a}}=B\\cdot k\\cdot H\\cdot s,\\qquad V_{\\text{recv}}=B\\cdot k\\cdot H\\cdot s$$</div>\n<p>注意这个量正比于 B·k 而非总参数量，这正是 MoE 通信可控的机制根源；但它是每层都发生的，层数一乘就变成可观的总量。举例：一个解码步内 B 个 token 各选 k 个专家，若某设备持有 E 分之一的专家，它平均收到 B·k/E 个 token 的激活，但最忙设备收到的量由路由分布决定，可能数倍于均值——均值算带宽、峰值定延迟，这是 EP 容量规划必须分开算的两笔账。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-33\">三十三 · Blackwell 上的物理链路：NVLink 5 与 NVSwitch 决定 All-to-All 的下限</h3>\n<p>在 GB200/GB300 NVL72 机架内，GPU 之间经 NVLink 5 与 NVSwitch 构成全互联域，任意两卡之间是一跳，这使 All-to-All 不必走多跳胖树或环状算法，通信模式从“带宽受限的环形接力”变成“交换结构下的并发点对点”。对 EP 而言这是关键：All-to-All 的瓶颈从链路跳数转移到交换机端口带宽与端点注入速率。工程判断是，只要专家并行度落在单个 NVLink 域内，All-to-All 的时延主要由端点侧的打包、索引重排与内核启动构成，而非链路本身；一旦 EP 度跨出该域、需要经 InfiniBand 或以太网跨机架，通信代价立刻跃升一个档位，路由偏斜的尾延迟也被放大。因此拓扑选择的第一原则是让最热的那条通信路径留在 NVLink 域内，把跨域通信留给层间激活或 KV 传输这类低频、可流水重叠的流量。</p>\n<p>代价核算要落到具体机制上。All-to-All 的实际耗时近似为固定开销加传输时间：</p>\n<div class=\"formula\">$$T_{\\text{a2a}}\\approx T_{\\text{launch}}+T_{\\text{pack}}+\\frac{V_{\\text{a2a}}}{BW_{\\text{eff}}}$$</div>\n<p>其中 BW_eff 是端点可达的有效带宽，受并发流数、消息大小与协议开销影响。小消息下 T_launch 与 T_pack 占主导，这意味着解码阶段（B 小、每 token 只发 H 维向量）的 All-to-All 极易被启动开销吞掉，而预填阶段（B 大）才是带宽主导。具体例子：同一层在预填时 B 达数千 token，All-to-All 是带宽题；切到逐 token 解码时 B 降到几十，同样的链路却变成时延题，此时把多个解码步的 token 攒批再发、或把 All-to-All 与分组 GEMM 做流水重叠，比单纯加带宽更有效。这也是连续批处理与 EP 必须联合设计的原因。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-34\">三十四 · NIXL 与传输层：把“搬 token”从集合通信里解耦</h3>\n<p>NIXL 这类传输抽象的价值在于把数据搬运从集合通信原语中拆出来，允许点对点、异步、带描述符的传输，并可在 NVLink、InfiniBand、甚至存储后端之间统一寻址。对 MoE 推理的直接意义是：All-to-All 不必被实现为一个刚性同步的集合操作，而可以拆成“按目标设备分组的异步写 + 完成通知”，从而与分组 GEMM 的计算重叠。分离式预填/解码架构下，KV cache 从预填节点搬到解码节点也走同一套传输面，使专家权重的静态分布与 KV 的动态流动共享一条数据通路。</p>\n<p>但解耦带来新的代价：异步传输需要显式缓冲与完成跟踪，接收侧必须等齐所有来源的分片才能启动分组 GEMM，最慢的那条流决定整层进度。设单层有 E 个来源设备，各流完成时间为 t_i，则接收侧可启动计算的时刻是 max(t_i) 而非均值——这就是尾延迟的数学形态。工程上要么做分片到达即计算的部分聚合（牺牲 GEMM 形状规整性），要么接受等待。显存侧同样要付账：双缓冲的接收区、索引张量与门控权重中间结果都要驻留，容量规划时不能只算专家权重与 KV cache。定性地说，传输层越灵活，越需要调度器显式管理缓冲生命周期，否则重叠收益会被额外的拷贝与同步抵消。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-35\">三十五 · All-Reduce 与 All-to-All 的瓶颈判据</h3>\n<p>两类通信的瓶颈条件不同，必须分开判断。TP 的 All-Reduce 每层两次，通信量正比于 B·H，与路由无关，形状固定，因此它的瓶颈是纯带宽题：只要 TP 度不超过 NVLink 域、且能与相邻算子重叠，它通常不是首要瓶颈。EP 的 All-to-All 则同时受带宽与偏斜支配，判据可以写成“最忙设备的排队时间是否超过该层分组 GEMM 的计算时间”。若超过，通信就是瓶颈；若未超过且能与计算重叠，通信被隐藏。用伪代码表达调度器的判断逻辑：</p>\n<ul>\n<li>对每个解码步，统计各专家的 token 计数直方图；</li>\n<li>按 EP 映射求每设备接收量，取最大值与均值之比作为偏斜度；</li>\n<li>若偏斜度超过阈值，触发容量因子下调或路由温度调整，牺牲少量 token 换负载平整；</li>\n<li>若 All-to-All 预估时延大于分组 GEMM 预估时延，则增大攒批窗口或启用跨层重叠；</li>\n<li>否则按当前批继续，仅记录尾延迟分位数供 SLO 监控。</li>\n</ul>\n<p>具体例子：某层路由把大量 token 集中到少数专家，持有这些专家的设备接收量远超均值，其 All-to-All 接收队列与分组 GEMM 同时变长，而其余设备空转等待下一层同步点。此时系统吞吐由最忙设备决定，平均利用率指标会严重高估实际能力。这正是“只报告平均吞吐会低估 SLO 违约风险”的机制来源——尾延迟不是噪声，是拓扑与路由分布的结构性产物。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-36\">三十六 · 通信何时成为瓶颈：三个可操作的判据</h3>\n<p>第一个判据是算术强度。分组 GEMM 的 M 维等于每专家实收 token 数，当路由偏斜使部分专家的 M 很小，该专家的 GEMM 变成低算术强度的小矩阵乘，计算时间缩短但通信量不变，通信占比被动上升。此时瓶颈不在链路带宽，而在“通信无法被足够长的计算掩盖”。第二个判据是并行度与域边界：EP 度一旦跨出 NVLink 域，单次 All-to-All 的固定开销与有效带宽同时恶化，原本可隐藏的通信立刻显形；因此扩 EP 度前应先确认域内是否还有余量。第三个判据是批形态：预填阶段大 B 使通信成为带宽题且易与计算重叠，解码阶段小 B 使通信成为时延题，同一拓扑在两个阶段的瓶颈位置不同，容量规划必须按阶段分别做，而不是取一个混合平均值。</p>\n<p>显存与功耗也参与这个判断。EP 度越高，单卡专家权重越少、KV cache 空间越宽裕，但 All-to-All 的并发流与缓冲增多，端点注入功耗上升；TP 度越高，单卡权重分片越小但 All-Reduce 频次不变。存在一个使“权重显存可行、通信可隐藏、尾延迟可控”三者同时成立的并行度区间，工程任务就是把这个区间找出来并用容量因子与攒批窗口在其中做微调。材料未给出 Mixtral 的具体专家数与拓扑，因此这里只能给出判据与公式形态，具体数值须由部署侧的直方图与分位数监控填充。</p>\n<p>最后落在机制上：把每专家 token 计数直方图、All-to-All 各流完成时间的最大值、分组 GEMM 的 M 维分布三者作为同一组运行时指标联合采集，用偏斜度与“通信时延/计算时延”比值作为触发信号，联动调整容量因子、攒批窗口与 EP 映射。通信是否成为瓶颈，最终不是由链路标称带宽回答，而是由最忙设备在同步点前的排队时间回答。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-37\">三十七 · 专家并行的通信边界：All-to-All 何时压过分组 GEMM</h3>\n<p>在 Mixtral 的推理链路上，专家并行（EP）把每层 N 个专家按编号切到不同设备，token 必须先离开原设备才能被本地专家计算。这一步的通信量由路由结果直接决定：设批内 token 数为 B、top-k 为 k、隐藏维为 H、精度为 b 字节，则单层单向 All-to-All 的字节量近似为 <span class=\"formula\">$$V_{\\mathrm{a2a}}\\approx B\\cdot k\\cdot H\\cdot b$$</span> 且每层要往返两次（去程送 token，回程送专家输出）。关键在于这个量随 B 线性增长，而分组 GEMM 的计算量只随被激活的 token 数增长——当批做大以摊薄权重读取时，通信的增长斜率反而更陡。Blackwell 档位上 NVLink 5 与 NVSwitch 提供的是机架内高带宽域，跨 NVL72 之外的节点则退化为 RDMA 路径，NIXL 负责在这两类传输之间做端点抽象；一旦 EP 度超出单 NVLink 域，All-to-All 的时延台阶会明显抬升，此时通信开始成为瓶颈而非计算。</p>\n<p>判断瓶颈归属需要一个可算的比值。设单设备本地专家 GEMM 的有效算力为 F、单向链路带宽为 W，则单层通信时间与计算时间之比约为 <span class=\"formula\">$$\\rho=\\frac{2BkHb/W}{Bk\\cdot 2\\cdot H\\cdot D\\cdot \\text{util}/F}=\\frac{bF}{WD\\cdot\\text{util}}$$</span> 其中 D 为每专家 FFN 的中间维、util 为分组 GEMM 的实际利用率。注意 ρ 与批大小无关——这解释了为什么“加大批”不能救通信瓶颈：它同时放大分子分母。真正能压低 ρ 的是提高 util（让分组 GEMM 形状更整齐）或减少跨设备交换（降低 EP 度、改用 TP 承担部分切分）。反过来，路由偏斜会让 util 掉到很低，ρ 被动升高，此时即便平均带宽充裕，最忙设备上的排队仍会把尾延迟推高。</p>\n<p>容量因子在这里与通信耦合。容量上限 C 越小，被丢弃的 token 越多，实际参与 All-to-All 的 token 数下降，通信量随之下降，但丢弃率上升直接损伤生成质量；C 放大则通信与显存中间张量同步膨胀。工程上应把每专家 token 计数、丢弃率、All-to-All 时延与分组 GEMM 形状分布一起采集，用 ρ 的实测值决定是否把 EP 度回退、把部分专家复制到多设备（冗余专家以吸收热点）或改用 TP+EP 混合拓扑。下表给出拓扑选择与代价的对应关系：</p>\n<table class=\"mini\"><thead><tr><th>拓扑</th><th>通信形态</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>纯 EP</td><td>每层两次 All-to-All</td><td>通信随 B·k 线性增长，跨域时延台阶</td><td>EP 度超出单 NVLink 域、路由重度偏斜</td></tr><tr><td>TP+EP</td><td>All-Reduce 叠加 All-to-All</td><td>All-Reduce 与 All-to-All 争用同一链路</td><td>TP 度大而 H 小，归约开销占比过高</td></tr><tr><td>PP+EP</td><td>阶段间点对点激活传递</td><td>流水气泡，阶段不均衡放大尾延迟</td><td>层间专家负载差异大、微批切分过细</td></tr><tr><td>DP+EP</td><td>副本间无 token 交换，仅权重分片</td><td>显存容纳全部专家权重</td><td>总参数超出单机显存，需跨节点分片</td></tr></tbody></table>\n<p>一个具体例子：长上下文请求混合短请求时，批内 token 总数被长序列抬高，All-to-All 量按 B·k·H 上升，而分组 GEMM 的 M 维被容量因子截断后并不等比增长，ρ 升高，首 token 延迟与每 token 间隔同时恶化；此时把 EP 度从跨节点回退到机架内、并用冗余专家吸收热点专家，比单纯调大容量因子更能守住 SLO，因为后者只是把通信换成丢弃。需要标注的是，材料未给出 NVFP4/FP8 下路由打分与门控权重的数值行为，低精度会同时压缩 V_a2a 的分子 b 与分组 GEMM 的算力项，ρ 的实际走向必须在目标拓扑上实测，不能由稠密模型的通信经验外推。</p>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-38\">三十八 · 精度塌陷：从门控权重到分组 GEMM 的数值链路</h3>\n<p>在 Mixtral 这类 top-k 路由结构里，精度塌陷不是单一算子的问题，而是一条链路上的逐级放大：路由器 logits → softmax 门控权重 → 加权求和写回残差流。门控权重本身是归一化后的概率，k 个专家的权重之和为 1，单个权重在 k=2 时典型落在 0.5 附近；一旦低精度量化把 softmax 输出压到少数几个离散档位，两个专家的相对权重就被抹平，输出退化为近似等权平均，生成质量出现与吞吐无关的静默下滑。诊断上不能只看 loss 或困惑度，要在推理链路里插入探针：每层记录门控权重的熵与 top-1 与 top-2 权重差，熵骤降说明路由打分被量化压塌。</p>\n<div class=\"formula\">$$H_i=-\\sum_{j\\in\\mathrm{TopK}(g_i)}w_{ij}\\log w_{ij},\\qquad \\Delta_i=w_{i,(1)}-w_{i,(2)}$$</div>\n<p>工程代价体现在两个方向：为保精度而保留路由打分与门控权重的 FP32/BF16，会让每层多出一份 B×N 的打分矩阵与 softmax 中间量，在长上下文、大并发下这部分显存与带宽不可忽略；反之把门控也压到低精度，省下的是小头，赔进去的是整层输出的数值稳定性。具体例子：某层 N 个专家、批内 B 个 token，打分矩阵 B×N 若以 BF16 存放占 2BN 字节，改为 FP8 省一半，但 softmax 在 FP8 下对 logits 的动态范围极为敏感，接近饱和的 logits 会让权重分布塌成 one-hot，等于把 top-k 退化为 top-1。判断标准是：路由打分与门控权重保持在较高精度，专家 FFN 的权重与激活才谈低精度，两者不能一刀切。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-39\">三十九 · OOM：专家权重、KV cache 与路由中间张量的三方挤占</h3>\n<p>MoE 推理的显存账本与稠密模型不同：总参数量远大于激活参数量，但全部专家权重必须常驻或可快速换入，容量规划要把三块同时计入——专家权重、KV cache、路由中间张量。OOM 往往不是单一峰值触发，而是批调度把并发推高后，KV cache 按层线性增长，与专家权重争夺同一块 HBM。定位方法是把显存占用按这三块打标签做时间序列采样，看 OOM 前哪一块斜率最陡：若 KV cache 陡增，是批大小与序列长度失控；若路由中间张量陡增，是 B×N 打分矩阵与分组索引在超大 batch 下膨胀；若专家权重侧出现换入换出，是专家并行度与单卡容量不匹配。</p>\n<p>代价上，专家权重占的是静态大头，KV cache 是动态大头，两者此消彼长。具体例子：专家并行下每卡只持有本地专家，单卡权重容量随专家并行度线性下降，但 All-to-All 的中间缓冲区随批内 token 数上升；把批大小翻倍换吞吐，可能同时把 KV cache 与通信缓冲区推过阈值，触发 OOM 或迫使调度器回退批大小，形成吞吐不升反降。工程判断是给三块分别设硬上限并按最紧的一块反推批大小，而不是等 OOM 后被动重试。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-40\">四十 · 批抖动与尾延迟：分组 GEMM 形状与 All-to-All 排队的耦合</h3>\n<p>分组 GEMM 的 M 维等于每专家实际收到的 token 数，随路由分布逐层、逐批动态变化。平均吞吐好看不代表 SLO 达标：偏斜流量下最忙设备的排队时间决定尾延迟，而形状抖动让 kernel 利用率在大小核之间来回切换。诊断要采集两个分布而非两个均值——每专家 token 计数的分布，以及分组 GEMM 形状的分布；前者偏斜说明路由塌缩或负载不均，后者方差大说明批内路由不稳定。尾延迟的直接来源是这两者的耦合：某设备分到的 token 多，GEMM 时间长，反向 All-to-All 又要等最慢设备，整批被最忙设备拖住。</p>\n<div class=\"formula\">$$T_{\\mathrm{batch}}\\approx \\max_{d}\\left(T^{\\mathrm{fwd}}_{\\mathrm{comm},d}+T^{\\mathrm{GEMM}}_{d}+T^{\\mathrm{bwd}}_{\\mathrm{comm},d}\\right)$$</div>\n<p>代价是吞吐与尾延迟的取舍：容量因子调大能减少丢弃、让形状更饱满，但显存与计算浪费上升；调小则丢弃率上升、质量下降，同时形状更碎、kernel 利用率更差。具体例子：k=2、批内 token 数固定时，若路由把 60% 的 token 压到少数专家，这些专家的分组 GEMM M 维远超均值，而其余专家空转，All-to-All 的发送端出现长队列；此时平均吞吐可能仍达标，但 P99 每 token 间隔已经违约。定位手段是把每层每专家的 token 计数与 GEMM 时长做成热力图，找持续偏斜的层与专家，再决定是调容量因子、调 top-k 还是改并行拓扑。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-41\">四十一 · 静默降级：容量丢弃与路由塌缩的无告警失效</h3>\n<p>最危险的失败模式不报错：容量因子截断把超出上限的 token 掩码丢弃，该层对这些 token 的输出为零、只保留残差连接，生成继续但质量已降。丢弃率随路由偏斜上升，而系统指标（吞吐、显存、GPU 利用率）可能全部正常，形成静默降级。监控必须把容量丢弃率作为一等指标，按层、按专家、按批统计，并与门控权重熵、专家利用率一起看：丢弃率上升叠加专家利用率集中，基本可判定路由塌缩或流量偏斜。</p>\n<p>代价是质量与吞吐的隐性交换：丢弃 token 省下的是被丢弃 token 的专家计算与通信，换来的是生成连贯性下降，且这种下降在短请求上不明显、在长上下文与多轮对话里累积。具体例子：某层容量因子设为固定值，偏斜流量下最忙专家收到 token 数超过上限，多出的 token 被丢弃并跳过该层 FFN；这些 token 的残差流缺少前馈变换，后续层的路由打分随之偏移，错误逐层传播。工程判断是容量丢弃率设阈值告警并联动容量因子，而不是把它当作正常损耗；同时保留被丢弃 token 的计数用于回滚决策。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-42\">四十二 · 监控、定位与回滚：把旋钮做成可回退的状态机</h3>\n<p>监控面要覆盖四类信号：每专家 token 计数与利用率、容量丢弃率、All-to-All 时延分布、分组 GEMM 形状与时长分布；再叠加门控权重熵与 top-1/top-2 权重差作为精度探针。定位路径是从尾延迟违约出发，先看最忙设备的通信与 GEMM 时长，再看该设备的专家 token 计数是否偏斜，最后看门控权重分布是否塌缩；三条线索指向同一层同一专家时，问题定位完成。回滚不是重启，而是把运行时旋钮退回上一组稳定配置：容量因子、top-k、批大小上限、专家并行度，按违约率与丢弃率的联动关系逐项回退。</p>\n<ul>\n<li>容量因子：丢弃率超阈值时上调，尾延迟违约时下调，两个方向互斥，需按 SLO 优先级排序。</li>\n<li>top-k：k 增大提升质量但抬高激活计算与通信量，k 减小省算力但加剧路由集中。</li>\n<li>批大小上限：与 KV cache 和通信缓冲区联动，OOM 前先降批大小而非降专家并行度。</li>\n<li>精度档位：门控权重与路由打分保持高精度，专家 FFN 低精度可独立回退。</li>\n</ul>\n<p>具体例子：一次尾延迟违约中，监控显示某设备 All-to-All 发送队列长、该设备本地专家 token 计数为均值的数倍、门控权重熵偏低；回滚动作是先降批大小上限缓解缓冲区压力，再上调容量因子减少丢弃，最后若偏斜持续则临时提高负载均衡强度或调整专家到设备的映射。回滚的判据是违约率与丢弃率同时回到阈值内，而非单看吞吐恢复。这套状态机的关键在于每个旋钮都有明确的观测指标与回退顺序，避免在偏斜流量下同时动多个旋钮导致无法归因。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-43\">四十三 · 路由偏斜下的五类失效与可观测闭环</h3>\n<p>Mixtral 推理的失效几乎都从同一个源头长出：每层路由分布是离散且随批变化的，容量因子 C 把这种随机性截断成硬边界。设某层批内 B 个 token、N 个专家、top-k 路由，专家 j 实际收到的 token 数为 M_j，则容量上限为 ⌈C·B·k/N⌉，丢弃指示可写成 <span class=\"formula\">$$d_j=\\max(0,\\;M_j-\\lceil C\\cdot B\\cdot k/N\\rceil)$$</span>，总丢弃率 D=Σd_j/(B·k)。D 不是常数：同一模型在短请求混合批下接近零，在长上下文、领域高度集中的批下会明显抬升。工程上必须把 D 与每专家计数 M_j 一起采集，单看平均吞吐会把“丢 token 换来的快”误判为容量充裕。精度塌陷的第一表征正是 D 突增而 perplexity 或人工抽检质量下滑，且下滑集中在被丢弃 token 所在的层与位置——残差直通使该层专家输出为零，等价于对这部分 token 做了粗暴剪枝。</p>\n<p>第二类是 OOM 与显存碎片。MoE 的显存账单由三块构成：全部专家权重（总参数量远大于激活量）、KV cache、以及路由中间张量（B×N 打分、B×k 索引、分组重排缓冲与 All-to-All 收发缓冲）。容量规划应写成 <span class=\"formula\">$$W_{\\text{total}}=N\\cdot W_{\\text{expert}}+W_{\\text{router}}+S\\cdot L\\cdot H_{\\text{kv}}+B\\cdot N\\cdot b_{\\text{score}}$$</span>，其中前两项与批无关，后两项随并发线性增长。危险点在于专家并行下每设备只驻留本地专家，但 All-to-All 缓冲按最忙专家规模分配；路由偏斜时缓冲按峰值而非均值膨胀，OOM 往往发生在“平均显存还有余量”的时刻。诊断手段是分设备打印权重、KV、通信缓冲三段占用，并观察其随批大小的斜率——斜率异常陡的那一段就是瓶颈。</p>\n<p>第三、四类是批抖动与尾延迟。分组 GEMM 的 M 维等于 M_j，形状随路由动态变化，kernel 利用率在 M_j 很小时急剧下降；同时 All-to-All 的完成时间由最忙设备决定，形成木桶效应。可定义的抖动指标为 <span class=\"formula\">$$J=\\frac{\\max_j M_j}{\\frac{1}{N}\\sum_j M_j}$$</span>，J 接近 1 表示均衡，J 显著大于 1 时尾延迟由该设备排队主导。监控应采集每层 J 的分布、分组 GEMM 的 M 维直方图、All-to-All 的 p99 时延，而不是只报 step 平均耗时。批调度层面，连续批处理把不同长度请求混在一起会放大 J；按路由亲和度做批内聚类（把可能命中同一专家的 token 聚到一批）能压低 J，代价是调度器需要维护路由预测或历史统计，增加调度开销与实现复杂度。</p>\n<p>第五类是静默降级，也是最难定位的一类：容量丢弃不报错、All-to-All 超时被重试掩盖、低精度下路由打分与门控权重的数值漂移使 top-k 选择翻转。后者在 NVFP4/FP8 部署中尤其需要单独验证——材料未给出量化细节，因此不能假设门控权重在低精度下保持排序稳定。工程判断是：把“每专家 token 计数、丢弃率 D、抖动 J、All-to-All p99、分组 GEMM 形状分布”五项做成每层可下钻的指标，并设两条硬阈值——D 超过设定上限即触发容量因子上调或拒绝新批，J 超过阈值即触发批重排。回滚路径应分级：先调 C 与 top-k 运行时旋钮（无损、秒级），再回退批调度策略，最后才回退量化档位与并行拓扑；每次变更记录 D、J 与 SLO 违约率的联动，避免把质量回退误归因于模型本身。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>首要观测量</th><th>典型触发条件</th><th>首选动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>丢弃率 D、分层质量抽检</td><td>长上下文、领域集中批</td><td>上调 C 或拆批</td></tr><tr><td>OOM</td><td>分设备三段显存斜率</td><td>偏斜峰值撑大通信缓冲</td><td>限并发、缩缓冲</td></tr><tr><td>批抖动</td><td>抖动 J、GEMM M 维直方图</td><td>变长请求混批</td><td>按路由亲和重排批</td></tr><tr><td>尾延迟</td><td>All-to-All p99</td><td>最忙设备排队</td><td>专家并行再平衡</td></tr><tr><td>静默降级</td><td>top-k 翻转率、门控权重漂移</td><td>低精度权重部署</td><td>回退量化档位</td></tr></tbody></table>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-44\">四十四 · 口径先于数字：可比的三个锚点</h3>\n<p>读 Mixtral 这类 MoE 的推理基准，第一步不是看吞吐数字，而是确认三个锚点是否对齐：激活计算量、显存占用口径、以及批的构成方式。材料明确给出的一条机制事实是：激活计算量由 top-k 与专家 FFN 规模决定，而非总参数量。这意味着任何“参数量对比”在 MoE 与稠密模型之间天然失效——总参数远大于激活参数，用总参数去除吞吐会得到一个漂亮但无意义的比值。工程上应把分母换成每 token 激活 FLOPs，即</p>\n<div class=\"formula\">$$F_{\\text{act}} \\approx k \\cdot F_{\\text{expert-FFN}} + F_{\\text{router}} + F_{\\text{attn}}$$</div>\n<p>其中路由项是小线性层，通常可忽略；注意力项与序列长度线性相关，长上下文下不可省。第二个锚点是显存：显存必须容纳全部专家权重，容量规划须同时计入专家权重、KV cache 与路由中间张量，三者量级不同但都不能漏。第三个锚点是批的构成——变长请求混合下，每层路由的 token 总数决定分组 GEMM 的 M 维，同一 batch size 在短请求与长请求下产生的专家负载完全不同。三个锚点任一不对齐，跨实现的吞吐对比就不可比。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-45\">四十五 · 硬件档位与并行拓扑：材料未给出的部分怎么处理</h3>\n<p>给定材料未给出硬件档位与并行拓扑，也未给出专家数、隐藏维与层数的具体数值。这并不妨碍建立口径，但要求我们在报告任何数字时标注“拓扑未定”。在 Blackwell 档位上，专家并行度直接决定 All-to-All 的通信量：token 需经 All-to-All 发往持有对应专家的设备再送回，通信量与路由分布相关，偏斜流量会放大最忙设备的排队时间。可推的工程判断是：专家并行度越高，单设备专家权重越小、显存压力越低，但 All-to-All 跳数与尾延迟上升；并行度越低则相反。因此同一模型在两套拓扑上跑出的 TPOT 不可直接比较，除非同时报告并行度、每设备专家数与互联带宽档位。</p>\n<p>具体例子：假设 8 路专家并行、单层 N 个专家均分到 8 设备，每设备持 N/8 个专家。某解码步 B 个 token 的路由分布若集中在少数专家，则持有热门专家的设备排队，其余设备空转，反向 All-to-All 的完成时间由最慢设备决定。此时平均吞吐看似正常，但 TPOT 的 P99 已被最忙设备拉长。基准表若只给平均 TPOT，就把这条尾延迟藏掉了。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-46\">四十六 · batch 与并发：容量因子把两者绑在一起</h3>\n<p>批大小与并发度需按容量因子反推，使每专家 token 数接近上限而不大量丢弃。这是 MoE 基准里最容易被忽略的耦合：容量因子按每专家可接收 token 上限截断，超出部分被掩码丢弃并跳过该层专家计算。于是“增大 batch 提升吞吐”在 MoE 上不是单调的——batch 增大到某点后，路由偏斜使部分专家溢出，丢弃率上升，有效计算量不增反降，同时被丢弃 token 的输出为零、仅保留残差，生成质量受损。基准必须同时报告 batch、并发、容量因子与实测丢弃率，四者缺一，吞吐数字就无法复现。</p>\n<p>伪代码思路可写成：给定目标 SLO 的 TPOT 上限，先固定容量因子 C，扫描 batch 使每专家期望 token 数 μ_j 满足 μ_j ≤ C·(B·k/N)，再测丢弃率 d；若 d 超过质量阈值，则回退 batch 或提高 C。这里的代价是显存：C 过大时每专家缓冲区按上限分配，显存与计算浪费同时上升；C 过小时丢弃率上升。基准表若只给一个 batch 点，读者无法判断该点是否处于丢弃拐点附近。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-47\">四十七 · 指标口径：TTFT、TPOT、吞吐、显存、功耗各自的分母</h3>\n<p>TTFT 在 MoE 上受预填阶段路由与分组 GEMM 形状影响，预填 batch 大、token 多，分组 GEMM 的 M 维较大、kernel 利用率较好，但 All-to-All 一次性搬运的 token 量也大，首 token 延迟对互联带宽敏感。TPOT 则受解码步的小 batch 影响：解码时每步 token 少，分组 GEMM 的 M 维小，形状抖动导致 kernel 利用率不稳，是尾延迟的主要来源之一。吞吐必须声明是 token/s 还是请求/s，以及是否计入被丢弃 token——被丢弃 token 不产生专家计算，却仍占用调度与路由开销，把它算进吞吐会高估有效吞吐。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>分母/口径</th><th>MoE 特有陷阱</th></tr></thead><tbody><tr><td>TTFT</td><td>每请求首 token，含预填路由与 All-to-All</td><td>预填 batch 大时 All-to-All 带宽成为瓶颈</td></tr><tr><td>TPOT</td><td>解码步间隔，按 P50/P99 分报</td><td>分组 GEMM 形状抖动拉长 P99</td></tr><tr><td>吞吐</td><td>有效 token/s，剔除丢弃 token</td><td>丢弃 token 仍占调度开销</td></tr><tr><td>显存</td><td>专家权重 + KV cache + 路由中间张量</td><td>总参数远大于激活参数，权重占主导</td></tr><tr><td>功耗</td><td>每有效 token 能量</td><td>空转设备仍耗电，偏斜流量下能效下降</td></tr></tbody></table>\n<p>功耗口径尤其要注意：专家并行下部分设备空转但仍在供电，偏斜流量使每有效 token 能量上升。材料未给出功耗数字，因此只能定性判断能效随丢弃率与空转率恶化，不能引用具体瓦数。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-48\">四十八 · 哪些提升不可比：四类典型误读</h3>\n<ul>\n<li>跨参数量比吞吐：用总参数做分母，MoE 必然“更高效”，但这是定义使然，不是实现优势。应改用激活 FLOPs 或每 token 激活参数量。</li>\n<li>跨容量因子比质量：容量因子不同则丢弃率不同，质量差异混入了丢弃策略，不是模型本身差异。比较质量必须固定 C 并报告丢弃率。</li>\n<li>跨拓扑比 TPOT：并行度与互联档位不同，All-to-All 跳数与尾延迟不同，TPOT 不可直接比较。</li>\n<li>引用低精度收益：材料未给出 NVFP4/FP8 量化与 KV cache 压缩细节，低精度下路由打分与门控权重的数值行为需另行验证，在缺少量化材料时引用低精度收益属于无依据外推，应标注未给出。</li>\n</ul>\n<p>具体例子：某报告称 MoE 吞吐为稠密基线数倍，若基线是同等总参数的稠密模型，则这个倍数只反映稀疏性；若基线是同等激活参数量的稠密模型，倍数才反映分组 GEMM 与并行实现的真实效率。材料可确认的结论仅是：稀疏专家结构在总参数远大于激活参数时仍保持与同激活参数量稠密模型可比的计算开销，推理成本由激活专家数而非总参数决定。这句话本身就是口径声明，不是性能承诺。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-49\">四十九 · 消融维度的口径：没有数字时怎么读</h3>\n<p>材料未给出消融实验的具体设置与数值。可讨论的消融维度包括 top-k 取值、专家数量、容量因子与负载均衡损失系数对质量与负载分布的影响。读这类消融时，要区分“机制性单调关系”与“实测拐点”：top-k 增大提高激活计算量与质量上限，但每 token 激活 FLOPs 线性上升；专家数增大在固定激活量下降低单专家负载、加剧路由偏斜与 All-to-All 碎片；容量因子与丢弃率的关系是硬截断，拐点位置由路由分布决定而非模型结构决定。负载均衡辅助损失系数控制均衡强度，材料未给出该系数的具体取值，因此任何“均衡损失带来多少吞吐提升”的说法都无依据。</p>\n<p>工程判断落在监控上：基准应采集每专家 token 计数、容量丢弃率、All-to-All 时延与分组 GEMM 形状分布，这四项是把平均指标还原为尾延迟与质量代价的最小集合。只报告平均吞吐而忽略分组 GEMM 形状抖动与 All-to-All 尾延迟，会低估 SLO 违约风险；把容量因子当作固定常量而不随路由分布调整，会在流量偏斜时同时出现 token 丢弃与设备空转。基准的价值不在于给出一个可引用的倍数，而在于把这四个观测量与 batch、并发、C、拓扑一起钉死，使下一次测量可复现、可比较。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-50\">五十 · 基准口径的失效边界：从「平均吞吐」到「尾延迟账本」</h3>\n<p>Mixtral 这类 MoE 的基准数字之所以难读，根源在于它没有单一的可比标量。稠密模型报一个 tokens/s 基本能刻画系统状态，而 MoE 的吞吐是路由分布的泛函：同一模型、同一硬件、同一 batch，只要请求的领域构成变了，专家命中分布就变，分组 GEMM 的 M 维跟着变，最忙设备的排队时间也跟着变。因此读任何 MoE 基准，第一步不是看数字，而是问三件事：batch 是静态还是连续批处理下的动态批、并发是固定请求数还是固定 QPS、指标是端到端平均还是分位。缺任一项，数字不可比。工程上应把基准拆成「形状分布 + 时延分位 + 丢弃率」三元组，而不是一个吞吐峰值。一个具体机制：分组 GEMM 的有效算力利用率可写成</p>\n<div class=\"formula\">$$\\eta_{\\mathrm{GEMM}}=\\frac{\\sum_{j}M_j}{\\max_j M_j\\cdot N_{\\mathrm{dev}}},\\qquad M_j=\\min\\bigl(\\lceil C\\cdot T/N\\rceil,\\ \\text{tokens}_j\\bigr)$$</div>\n<p>其中 T 为该层 token 总数，N 为专家数，C 为容量因子。分子是所有专家实际处理的 token 总量，分母是最忙设备满载时的理论上限。路由偏斜时 max_j M_j 远大于均值，η 掉下来，但平均吞吐指标看不出来——它被批内其他层和空闲设备摊平了。代价落在尾延迟上：最忙设备的分组 GEMM 与反向 All-to-All 排队，直接推高 TPOT 的 P99。举例：一个混合了代码与多语种请求的批，代码 token 集中命中少数专家，这些设备的 M 维被撑满甚至触发容量截断，而其余设备空转；此时平均 TPOT 可能只涨一点，P99 却明显恶化，SLO 违约从尾部开始。所以基准必须报分位而非均值，且要标注并发口径。</p>\n<p>硬件档位与精度是不可比的第二道坎。Blackwell 上同一 MoE 跑 FP8 与 NVFP4，激活专家权重的显存占用与分组 GEMM 的 tensor core 吞吐都不同，但路由打分与门控权重在低精度下的数值行为材料未给出，不能假定 top-k 选择在量化后不变——打分接近的 token 可能因舍入翻转专家归属，改变负载分布，进而改变上面那个 η。这类二阶效应使「低精度带来吞吐提升」在 MoE 上不能线性外推：收益被路由抖动部分抵消，且抵消幅度依赖流量。容量规划上，显存账必须同时计三块：全部专家权重（总参数量，与激活参数量解耦）、KV cache（随并发与上下文线性增长）、路由中间张量（B×N 打分矩阵与分组索引，随 batch 与专家数增长）。三者中任何一项成为瓶颈，报出的吞吐都不代表另一配置下的吞吐。</p>\n<table class=\"mini\"><thead><tr><th>基准项</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>吞吐 tokens/s</td><td>同 batch 口径、同并发、同序列长度分布</td><td>静态批 vs 连续批处理混报</td></tr><tr><td>TTFT</td><td>同预填 chunk 大小、同专家并行度</td><td>预填与解码混算一个数</td></tr><tr><td>TPOT 分位</td><td>标注 P50/P99 与丢弃率</td><td>只报均值、隐去容量截断</td></tr><tr><td>显存</td><td>专家权重+KV+路由张量分列</td><td>只报权重、不计 KV 增长</td></tr></tbody></table>\n<p>最后一条工程判断：容量因子与 top-k 是运行时旋钮，基准若把它们当固定常量，就只测了一个点而非一条曲线。可复现的 MoE 基准应扫描 C 与 k 的网格，同时记录每专家 token 计数、丢弃率、All-to-All 时延与分组 GEMM 形状直方图；只有形状分布与分位时延同时给出，两个数字才具备可比性。否则「提升」只是路由分布恰好均匀时的偶然切片，换一批请求即失效。</p>\n<h3 id=\"paper-mixtral-of-experts-2024-sec-51\">五十一 · 迁移到不同专家数与并行拓扑时的重排代价</h3>\n<p>把 Mixtral 这套 top-k 路由方案搬到别的模型上，第一件要改的不是模型代码，而是分组索引与并行拓扑的对应关系。原方案中，路由张量是 B×N 的打分矩阵，取 top-k 后得到 B×k 的专家编号；系统按专家编号稳定排序形成分组索引，专家并行下每个设备只处理本地专家对应的 token 子集。这个链路的代价随专家数 N 与并行度 P 的关系剧烈变化：当 N 不能被 P 整除时，必然出现持有专家数不均的设备，最忙设备的排队时间决定整层延迟。迁移到专家数更多的模型（例如把 N 从个位数抬到数十甚至上百）时，All-to-All 的通信量按每 token 的 k 个目标设备计，k 不变而目标设备集合扩大，意味着单次 All-to-All 的扇出变宽、消息更碎，NCCL 的集合通信效率下降。工程判断是：专家数扩张必须同步重设并行拓扑，优先保证 N 是 P 的整数倍，否则分组 GEMM 的 M 维在设备间天然不均，容量因子再调也压不住尾延迟。</p>\n<p>具体机制上，分组 GEMM 的 M 维等于每专家实际收到的 token 数，形状随路由动态变化。迁移到专家 FFN 更窄或更宽的模型时，这个 M 维与专家隐藏维的乘积决定单次 kernel 的算术强度；专家变窄则 M 维相对更重要，形状抖动对 kernel 利用率的影响被放大。代价可以写成一层内最忙设备的有效计算占比：</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_{j}\\min(c_j,\\,C)}{\\max_{j}\\lceil c_j/C\\rceil\\cdot C\\cdot P}$$</div>\n<p>其中 c_j 为专家 j 实际收到的 token 数，C 为容量上限，P 为设备数。η 越低，说明空转与排队越严重。迁移时若只改 N 不改 C 与 P，η 会随路由偏斜迅速下滑。例子：某层批内 B 个 token、k=2、N=8、P=8 时每设备恰好持有一个专家，分组 GEMM 形状只取决于该专家收到的 token 数；一旦迁到 N=64、P=8，每设备持 8 个专家，设备内还要再做一次子分组，M 维被切得更碎，单 kernel 启动开销占比上升，这是迁移到细粒度专家模型时最容易被低估的吞吐损失。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-52\">五十二 · 容量因子在变长负载与长上下文下的失效边界</h3>\n<p>容量因子是静态阈值，按每专家可接收 token 上限截断，超出部分被掩码丢弃并跳过该层专家计算。它在固定批形态下好用，但迁移到变长请求混合与长上下文场景时，边界立刻显现。每层路由的 token 总数等于批内所有序列当前步的 token 数之和，长上下文请求在预填阶段一次性灌入大量 token，单层 token 总数远超解码步；此时按解码步标定的容量因子会让预填层的丢弃率飙升，被丢弃 token 在该层输出为零、仅保留残差，直接损伤长上下文的首 token 质量。迁移到分离式预填/解码架构时，预填与解码必须使用两套容量因子，且预填侧更应偏向放大 C 而非丢弃，因为预填的 token 是一次性的、丢弃不可通过后续步补偿。</p>\n<p>代价侧写：丢弃率 d 与容量因子 C 的关系可由路由分布的偏斜度刻画。设专家 j 的期望负载为 λ_j，实际负载围绕 λ_j 波动，超出 C 的比例即丢弃率。C 过小则 d 上升、质量下降；C 过大则每专家预留的显存与计算浪费，分组 GEMM 的 M 维被 padding 撑大。迁移到 KV cache 占用高的长上下文模型时，显存预算被 KV 挤压，专家权重要全部驻留，容量因子能腾挪的空间更小，这是容量规划上的硬边界：总参数量远大于激活参数量，显存须同时计入专家权重、KV cache 与路由中间张量，三者中任何一项扩张都会压缩 C 的可调区间。工程判断是：迁移到长上下文模型时，把容量因子从全局常量改为按层、按预填/解码阶段分别设定，并监控每专家 token 计数与丢弃率的联动，而不是沿用单一阈值。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-53\">五十三 · 低精度迁移：路由打分与门控权重的数值边界</h3>\n<p>材料未给出 Mixtral 的量化方案，因此把该方案迁到 Blackwell 的 NVFP4/FP8 部署时，不能直接外推低精度收益。可判断的机制边界有两处。其一，路由器是一个小线性层，输出 N 维 logits 后取 top-k，top-k 是离散选择，logits 的微小扰动可能改变入选专家集合；低精度下打分矩阵的舍入误差若使两个专家的分数接近，路由结果会在不同步之间跳变，导致同一 token 在不同层、不同批中选中不同专家，分组索引随之抖动，分组 GEMM 形状更难稳定。其二，门控权重经 softmax 后加权求和，softmax 对 logits 差异敏感，低精度量化门控权重会引入系统性偏差，而该偏差直接乘在专家输出上进入残差流，逐层累积。</p>\n<p>迁移时的具体做法是：专家权重的分组 GEMM 可以用低精度，但路由打分与门控权重应保留较高精度或做 per-token 缩放，避免 top-k 边界翻转。代价体现在吞吐与数值稳定性的折中上——路由层计算量占比小，保留高精度对总吞吐影响有限，但对路由稳定性收益明确；反之若把路由也压到极低精度，省下的那点带宽远不足以补偿分组 GEMM 形状抖动带来的 kernel 利用率损失。例子：在专家数较多的模型上，N 维 logits 的量化误差随 N 增大而更容易造成 top-k 边界竞争，迁移到 N 大的模型时应优先保护路由精度。材料未给出 NVFP4/FP8 下路由打分与门控权重的数值行为，部署前须单独做数值验证，不能引用未给出的低精度收益。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-54\">五十四 · 从语言模型迁到其他领域：路由语义的前提是否成立</h3>\n<p>这套方案的隐含前提是 token 级路由：每个 token 独立选专家，专家子网络结构相同、可互换。迁到视觉、语音或多模态领域时，前提未必成立。视觉 token 的空间相关性强，相邻 patch 的路由若各自独立，容易在同一区域反复选中同一专家造成局部过载，而跨区域又分布稀疏；语音帧的时序连续性使路由在时间轴上抖动，同一音素在不同帧选中不同专家，分组 GEMM 的 M 维在帧间剧烈变化。这些领域的负载形态与变长文本请求不同，容量因子按文本解码步标定的经验不适用。工程判断是：迁移到空间或时序相关性强的领域时，路由应引入局部聚合（例如按 patch 块或帧窗共享路由决策），把 top-k 从逐 token 改为逐组，以牺牲少量路由粒度换取分组 GEMM 形状稳定与设备负载均衡。代价是激活计算量略升、路由表达力下降，但尾延迟与丢弃率可控。</p>\n<p>另一个边界是专家 FFN 的同构假设。原方案 N 个专家结构相同，分组 GEMM 可批处理；迁到专家异构（不同隐藏维、不同专家容量）的模型时，分组 GEMM 退化为逐专家独立 kernel，批处理收益消失，All-to-All 后的本地计算无法用单一形状描述。这类模型上该方案的吞吐优势被结构性削弱，应改用按专家分组、按形状分桶的调度，而不是沿用统一容量因子。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-55\">五十五 · 规模上限：什么条件下这套方案不再划算</h3>\n<p>规模上限不在总参数量，而在激活计算量与通信量的比值。MoE 推理吞吐高于同总参数稠密模型的机制根源是激活计算量由 k 与专家 FFN 规模决定，而非总参数量；但专家并行下 token 需经 All-to-All 发往持有对应专家的设备再送回，通信量与路由分布相关，偏斜流量放大最忙设备的排队时间。当专家 FFN 规模缩小、k 增大时，每 token 的激活计算量下降，而 All-to-All 的消息数与扇出上升，通信逐渐主导层延迟。可判断的临界条件是：单层 All-to-All 时延与分组 GEMM 计算时延可比时，继续扩大专家数或并行度不再带来吞吐收益。此时应收缩并行拓扑、把专家集中在更少设备上以减少跨设备交换，或改用专家复制加本地路由。</p>\n<p>显存是另一条上限。显存须容纳全部专家权重，总参数量远大于激活参数量，容量规划须同时计入专家权重、KV cache 与路由中间张量。迁到更大总参数的模型时，专家权重按总参数线性增长，而单卡显存固定，专家并行度被迫提高，通信占比随之上升——这两条上限互相咬合：显存逼你增加并行度，并行度又推高通信，最终在某个总参数档位上该方案的吞吐优势被通信吃掉。工程判断是：在给定互连带宽下，先按显存算出最小并行度，再验证该并行度下 All-to-All 时延是否可接受，若不可接受则说明该模型规模已超出这套拓扑的划算区间，需要换互连档位或改专家放置策略，而不是继续调容量因子。材料未给出拓扑细节与带宽数字，上述判断只能以定性方式落地为部署前的容量核算步骤。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-56\">五十六 · 迁移检查清单：把判断落成可执行项</h3>\n<p>迁移这套方案时，按以下顺序核对，每项都对应一个具体机制与代价。第一，专家数 N 与并行度 P 的整除关系，决定分组 GEMM 的 M 维是否天然均衡，不满足则先调拓扑再谈容量因子。第二，预填与解码是否共用容量因子，长上下文模型必须分设，否则预填层丢弃率不可控。第三，路由打分与门控权重的精度是否被低精度侵蚀，top-k 边界翻转会放大形状抖动。第四，领域 token 的相关性是否要求路由聚合，逐 token 路由在空间/时序数据上会造成局部过载。第五，专家是否同构，异构专家使分组 GEMM 批处理失效。第六，显存算出的最小并行度下 All-to-All 时延是否与计算时延可比，可比即触及规模上限。监控项对应为每专家 token 计数、容量丢弃率、All-to-All 时延与分组 GEMM 形状分布，这四项是把上述判断变成运行时信号的抓手；只报告平均吞吐而忽略形状抖动与尾延迟，会低估 SLO 违约风险。迁移的成败不取决于是否复刻原方案，而取决于是否在新模型与新领域上重新标定了容量因子、并行拓扑与路由粒度这三个旋钮。</p>\n\n<h3 id=\"paper-mixtral-of-experts-2024-sec-57\">五十七 · 迁移到新模型时的三个硬约束</h3>\n<p>把 Mixtral 这套 top-k 路由 + 容量因子 + 专家并行的方案搬到别的模型上，先要问的不是“能不能跑”，而是“哪一层结构假设会失效”。第一条硬约束是专家必须同构：分组 GEMM 之所以能把 B×k 个 token 拼成规则批次，前提是所有专家 FFN 的隐藏维与权重形状一致，一旦迁到异构专家（不同宽度、不同激活、甚至不同模态子网）模型，分组索引就不再能压成一个 M 维张量，只能退化为逐专家独立 kernel 或 padding 到最大形状，后者在显存与算力上直接按最大专家计费。第二条是路由器必须是每 token 独立打分的小线性层，迁到带跨 token 依赖的路由（如按序列或按块路由、可学习的全局槽位）时，B×N 打分矩阵不再能按 token 独立重排，All-to-All 的通信模式从“按专家编号散射”变成“按块聚合”，通信量随块大小而非 token 数增长。第三条是容量因子作为静态阈值的前提是批内路由分布可预测，迁到长上下文或高并发突发流量时，单批内的偏斜度方差变大，固定 C 的失效概率上升。</p>\n<p>规模上限不在参数量，而在“每设备专家数 × 每专家 token 数”与互连带宽的比值。设专家并行度为 E、单卡分到的专家数为 N/E、批内 token 数为 B、top-k 为 k，则单层每卡需接收的 token 数期望为 B·k/(N/E)，All-to-All 单层通信量近似正比于 B·k·d（d 为隐藏维），而分组 GEMM 的计算量为 B·k·(专家 FFN 的 FLOPs)。当 B·k·d 的通信时间超过分组 GEMM 计算时间，扩专家并行就从“省显存”变成“买延迟”：这正是 NVLink 5 域内与跨域 NIXL 传输的分界线，也是 NVL72 机架内专家并行与跨机架专家并行的判断依据。容量因子与丢弃率的关系可写成丢弃率 ≈ E[max(0, t_j/C − 1)]/B，其中 t_j 为专家 j 实际收到的 token 数；C 调大降丢弃但抬高显存与空转，C 调小反之，这个折中在迁移到新模型时必须按该模型的路由熵重新标定，不能沿用原模型的 C。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>失效机制</th><th>系统代价</th></tr></thead><tbody><tr><td>异构专家/多模态子网</td><td>分组 GEMM 形状不再统一</td><td>padding 至最大专家，显存与算力按最大者计</td></tr><tr><td>块级/序列级路由</td><td>token 独立重排假设破裂</td><td>All-to-All 通信量随块大小增长</td></tr><tr><td>突发高并发流量</td><td>固定容量因子失效</td><td>丢弃率与设备空转同时上升</td></tr><tr><td>低精度权重部署</td><td>路由打分与门控权重数值稳定性未验证</td><td>需单独验证，不能外推收益</td></tr></tbody></table>\n<p>不适用场景的判断要落到具体机制上：单请求低并发、序列极长的推理，路由的 token 总数小、分组 GEMM 的 M 维退化成小形状，kernel 利用率被固定开销吃掉，此时专家并行的 All-to-All 反而成为纯开销，稠密模型或张量并行更划算；专家数远大于批内 token 数时，大量专家在单批内零 token，容量因子失去意义，负载均衡辅助损失在推理侧无从施加，只能靠调度器做请求级路由亲和。迁移时真正要改的是三处：按新模型的路由熵重标定 C 与 top-k、按专家同构性决定分组 GEMM 还是逐专家 kernel、按互连域边界决定专家并行度上限；其余链路（重排、散射、门控加权、残差写回）可复用。规模上限的工程判断是：当单层 All-to-All 时延与分组 GEMM 形状抖动的尾延迟之和超过 SLO 的每 token 间隔预算时，继续加专家并行度只会放大违约率，此时应转向请求级亲和调度或降低专家并行度换域内带宽。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 121\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Mixtral of Experts</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"65.5\" x2=\"271.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 61.0 L 270.0 70.0 L 278.0 65.5 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"65.5\" x2=\"515.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 61.0 L 514.0 70.0 L 522.0 65.5 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"111.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2024 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Mixtral of Experts 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体评测数据集名称与规模。</td></tr><tr><td>基线</td><td>材料未给出稠密基线模型的具体参数量与对照设置。</td></tr><tr><td>主要结果</td><td>材料未给出可核验的基准分数、吞吐或延迟数字，因此不能引用具体提升幅度；可确…</td></tr><tr><td>消融</td><td>材料未给出消融实验的具体设置与数值；可讨论的消融维度包括 top-k 取值…</td></tr><tr><td>局限</td><td>材料未给出实验规模、硬件档位与失败模式统计。已知的机制性限制是：路由分布偏…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-mixtral-of-experts-2024 · 共 9 个片段</p>\n";break;}}})();
